object QuestionsExpansion6 {
    fun get(): List<Question> = tech() + nature() + mythologie() + gastronomie() + philosophie() + art() + litterature()

    private fun tech(): List<Question> = listOf(
        // ===== TECH (75 questions) =====
        Question(50526, "Quel est le langage de programmation créé par Guido van Rossum?", listOf("Java", "Python", "C++", "Go"), 1, "Tech", Difficulty.EASY, explanation = "Guido van Rossum a créé Python à la fin des années 1980, et le langage a été publié pour la première fois en 1991."),
        Question(50527, "En quelle année le premier iPhone a-t-il été lancé?", listOf("2005", "2007", "2009", "2011"), 1, "Tech", Difficulty.EASY, explanation = "Steve Jobs a dévoilé le premier iPhone le 9 janvier 2007, et il a été mis en vente aux États-Unis le 29 juin de la même année."),
        Question(50528, "Combien de boutons une souris standard possède-t-elle?", listOf("1", "2", "3", "5"), 2, "Tech", Difficulty.EASY, explanation = "La souris d'ordinateur standard comporte trois boutons : le clic gauche, le clic droit et la molette qui fait office de troisième bouton."),
        Question(50529, "Qu'est-ce que HTML?", listOf("Hyper Text Markup Language", "High Tech Marking Language", "Home Tool Modern Language", "Hyper Transfer Mark Logic"), 0, "Tech", Difficulty.EASY, explanation = "HTML est l'acronyme de HyperText Markup Language, le langage standard utilisé pour créer et structurer le contenu des pages web."),
        Question(50530, "Quel est le moteur de recherche le plus utilisé au monde?", listOf("Bing", "Yahoo", "Google", "DuckDuckGo"), 2, "Tech", Difficulty.EASY, explanation = "Google domine le marché des moteurs de recherche avec plus de 90 % des parts, grâce à son algorithme performant et son indexation massive du web."),
        Question(50531, "Quelle est la capacité d'un disque dur standard de 2023?", listOf("100 GB", "500 GB", "1 TB", "50 GB"), 2, "Tech", Difficulty.EASY, explanation = "En 2023, le disque dur standard pour un ordinateur personnel offre 1 To de stockage, soit environ 1 000 Go, car c'est un bon équilibre entre coût et capacité pour la majorité des utilisateurs."),
        Question(50532, "Quel est le système d'exploitation créé par Apple?", listOf("Windows", "macOS", "Linux", "Android"), 1, "Tech", Difficulty.EASY, explanation = "macOS est le système d'exploitation des ordinateurs Mac d'Apple, lancé en 2001 sous le nom de Mac OS X."),
        Question(50533, "Combien d'octets compose un kilobyte?", listOf("100", "512", "1000", "1024"), 3, "Tech", Difficulty.EASY, explanation = "En informatique, un kilobyte correspond à 1024 octets car les données sont comptées en base binaire (2^10). Cette convention diffère du système décimal où kilo signifie 1000."),
        Question(50534, "Quel est le protocole sécurisé pour naviguer sur internet?", listOf("HTTP", "FTP", "HTTPS", "SMTP"), 2, "Tech", Difficulty.EASY, explanation = "HTTPS est la version sécurisée du protocole HTTP, utilisant le chiffrement SSL/TLS pour protéger les données échangées entre le navigateur et le site web."),
        Question(50535, "Qu'est-ce qu'un algorithme?", listOf("Un type de virus", "Une suite d'instructions pour résoudre un problème", "Un composant électronique", "Un langage de programmation"), 1, "Tech", Difficulty.EASY, explanation = "En informatique, un algorithme est une séquence d'opérations définies pas à pas pour accomplir une tâche ou résoudre un problème, comme trier des données ou calculer un itinéraire."),
        Question(50536, "Quel est le nombre binaire équivalent à 10 en décimal?", listOf("1000", "1010", "1100", "1001"), 1, "Tech", Difficulty.MEDIUM, explanation = "10 en décimal vaut 1010 en binaire car il se décompose en 8+2, soit 1×2³ + 0×2² + 1×2¹ + 0×2⁰."),
        Question(50537, "Qu'est-ce que l'IA?", listOf("Intelligence Artificielle", "Internet Automatisé", "Interface d'Application", "Intégration Avancée"), 0, "Tech", Difficulty.MEDIUM, explanation = "L'IA, ou Intelligence Artificielle, désigne la capacité d'une machine à imiter des fonctions cognitives humaines comme l'apprentissage et la résolution de problèmes. Ce terme a été popularisé dans les années 1950 par John McCarthy."),
        Question(50538, "Quel langage est utilisé pour les feuilles de style web?", listOf("CSS", "XML", "SQL", "JSON"), 0, "Tech", Difficulty.MEDIUM, explanation = "CSS (Cascading Style Sheets) est le langage standard pour décrire la présentation et la mise en forme des documents web, comme les couleurs, polices et dispositions."),
        Question(50539, "En quelle année le web a-t-il été inventé par Tim Berners-Lee?", listOf("1989", "1991", "1995", "1998"), 1, "Tech", Difficulty.MEDIUM, explanation = "Tim Berners-Lee a proposé le concept du World Wide Web en 1989, mais le premier site web a été mis en ligne en 1991."),
        Question(50540, "Qu'est-ce qu'une API?", listOf("Application Programming Interface", "Advanced Personal Index", "Automated Process Integration", "Aggregated Platform Interface"), 0, "Tech", Difficulty.MEDIUM, explanation = "Une API est un ensemble de règles qui permet à deux applications logicielles de communiquer entre elles, comme un serveur de restaurant qui transmet les commandes des clients à la cuisine."),
        Question(50541, "Quel est le cloud computing?", listOf("Calcul sur un ordinateur local", "Stockage et calcul via internet", "Un type de virus informatique", "Un navigateur web"), 1, "Tech", Difficulty.MEDIUM, explanation = "Le cloud computing désigne la mise à disposition de ressources informatiques (stockage, puissance de calcul) via internet, permettant d'éviter la gestion de serveurs physiques locaux."),
        Question(50542, "Combien de pixels composent une image 4K?", listOf("1920x1080", "2560x1440", "3840x2160", "1280x720"), 2, "Tech", Difficulty.MEDIUM, explanation = "La résolution 4K standard est définie par 3840 pixels de large sur 2160 pixels de haut, soit environ 8,3 millions de pixels au total. Ce format est appelé Ultra HD."),
        Question(50543, "Qu'est-ce que JavaScript?", listOf("Un langage de programmation pour le web", "Un système d'exploitation", "Un type de serveur", "Un protocole réseau"), 0, "Tech", Difficulty.MEDIUM, explanation = "JavaScript est un langage de programmation principalement utilisé pour rendre les pages web interactives, côté client. Créé en 1995, il est aujourd'hui essentiel au développement web moderne."),
        Question(50544, "Quel est le fondateur de Microsoft?", listOf("Steve Jobs", "Bill Gates", "Mark Zuckerberg", "Larry Page"), 1, "Tech", Difficulty.MEDIUM, explanation = "Bill Gates a cofondé Microsoft avec Paul Allen en 1975, lançant ainsi l'un des plus grands éditeurs de logiciels au monde."),
        Question(50545, "Qu'est-ce que le machine learning?", listOf("L'apprentissage automatique", "Un type de serveur", "Un câble réseau", "Un protocole FTP"), 0, "Tech", Difficulty.MEDIUM, explanation = "Le terme anglais \"machine learning\" a été officialisé en français comme \"apprentissage automatique\" par la Commission d'enrichissement de la langue française en 2017."),
        Question(50546, "Quel est le langage de programmation privilégié pour l'analyse de données?", listOf("Python", "C++", "Java", "Swift"), 0, "Tech", Difficulty.HARD, explanation = "Python est largement utilisé en analyse de données grâce à ses bibliothèques spécialisées comme Pandas, NumPy et Matplotlib, qui simplifient la manipulation et la visualisation des données."),
        Question(50547, "Qu'est-ce que la blockchain?", listOf("Un type de mur", "Une technologie de chaîne de blocs décentralisée", "Un câble électrique", "Un système d'exploitation"), 1, "Tech", Difficulty.HARD, explanation = "La blockchain est un registre numérique distribué où les données sont stockées en blocs liés cryptographiquement, garantissant transparence et sécurité sans autorité centrale."),
        Question(50548, "Quel est le fondateur de Tesla?", listOf("Bill Gates", "Elon Musk", "Steve Wozniak", "Jack Ma"), 1, "Tech", Difficulty.HARD, explanation = "Elon Musk a cofondé Tesla en 2003, mais il n'en est pas le créateur initial : il a rejoint l'entreprise après sa fondation par Martin Eberhard et Marc Tarpenning."),
        Question(50549, "Qu'est-ce que la cybersécurité?", listOf("Un jeu vidéo", "La protection contre les attaques informatiques", "Un type de serveur", "Un navigateur web"), 1, "Tech", Difficulty.HARD, explanation = "La cybersécurité désigne l'ensemble des pratiques, technologies et processus conçus pour protéger les systèmes, réseaux et données contre les accès non autorisés, les attaques ou les dommages."),
        Question(50550, "Quel est le précurseur de la Nintendo Switch?", listOf("Nintendo Wii U", "Nintendo 64", "GameCube", "Game Boy"), 0, "Tech", Difficulty.HARD, explanation = "La Wii U, sortie en 2012, est le précurseur direct de la Switch car elle introduisait déjà un concept hybride avec un écran tactile sur sa manette, le GamePad."),
        Question(50551, "Qu'est-ce que le deep learning?", listOf("Un type de serveur", "Un domaine du machine learning utilisant les réseaux de neurones", "Un langage de programmation", "Un protocole réseau"), 1, "Tech", Difficulty.HARD, explanation = "Le deep learning est une sous-catégorie du machine learning qui s'inspire du cerveau humain en utilisant des réseaux de neurones artificiels à plusieurs couches pour analyser des données complexes."),
        Question(50552, "Quel est le fondateur de Facebook?", listOf("Bill Gates", "Steve Jobs", "Mark Zuckerberg", "Jack Ma"), 2, "Tech", Difficulty.HARD, explanation = "Mark Zuckerberg a cofondé Facebook en 2004 avec ses camarades de l'université Harvard, Eduardo Saverin, Andrew McCollum, Dustin Moskovitz et Chris Hughes."),
        Question(50553, "Qu'est-ce que la réalité virtuelle?", listOf("Un jeu vidéo", "Une simulation informatique immersive d'environnements", "Un type de serveur", "Un langage de programmation"), 1, "Tech", Difficulty.HARD, explanation = "La réalité virtuelle plonge l'utilisateur dans un monde numérique en 3D via un casque, créant une expérience interactive et immersive qui simule des environnements réels ou imaginaires."),
        Question(50554, "Quel est l'ordre de magnitude d'une exabyte en octets?", listOf("10^15", "10^18", "10^21", "10^12"), 1, "Tech", Difficulty.EXPERT, explanation = "Le préfixe \"exa\" dans le Système international d'unités correspond à 10^18, soit un milliard de milliards d'octets."),
        Question(50555, "Qu'est-ce que le quantum computing?", listOf("Un type de serveur traditionnel", "L'informatique utilisant les qubits et les principes de la mécanique quantique", "Un langage de programmation", "Un navigateur web"), 1, "Tech", Difficulty.EXPERT, explanation = "Contrairement aux bits classiques (0 ou 1), les qubits exploitent la superposition et l'intrication quantique pour effectuer certains calculs bien plus rapidement."),
        Question(50556, "Quel est le créateur de Linux?", listOf("Richard Stallman", "Linus Torvalds", "Bill Gates", "Steve Jobs"), 1, "Tech", Difficulty.EXPERT, explanation = "Linus Torvalds a créé le noyau Linux en 1991 alors qu'il était étudiant à l'Université d'Helsinki, en Finlande."),
        Question(50557, "Qu'est-ce que la cryptographie asymétrique?", listOf("Un type de serveur", "Un système utilisant deux clés: une publique et une privée", "Un langage de programmation", "Un protocole FTP"), 1, "Tech", Difficulty.EXPERT, explanation = "La cryptographie asymétrique repose sur une paire de clés mathématiquement liées : la clé publique, partagée librement, et la clé privée, gardée secrète. Cela permet de chiffrer un message avec la clé publique et de le déchiffrer uniquement avec la clé privée correspondante."),
        Question(50558, "Quel est le fondateur de Apple?", listOf("Bill Gates", "Steve Jobs", "Mark Zuckerberg", "Larry Page"), 1, "Tech", Difficulty.MEDIUM, explanation = "Steve Jobs a cofondé Apple en 1976 avec Steve Wozniak et Ronald Wayne, et en a été le PDG emblématique jusqu'à son décès en 2011."),
        Question(50559, "Qu'est-ce que le 5G?", listOf("Une version de WiFi", "La cinquième génération de technologie mobile", "Un type de serveur", "Un langage de programmation"), 1, "Tech", Difficulty.MEDIUM, explanation = "La 5G fait suite à la 4G (LTE) et offre des débits plus élevés et une latence réduite pour les communications mobiles."),
        Question(50560, "Quel est le protocole de messagerie électronique sécurisée?", listOf("HTTP", "SMTP", "PGP", "FTP"), 2, "Tech", Difficulty.MEDIUM, explanation = "PGP (Pretty Good Privacy) est un protocole de chiffrement et de signature numérique utilisé pour sécuriser les emails, garantissant confidentialité et authentification."),
        Question(50561, "Qu'est-ce qu'un GPU?", listOf("General Processing Unit", "Graphics Processing Unit", "Global Protocol Unit", "Government Processing Unit"), 1, "Tech", Difficulty.MEDIUM, explanation = "Un GPU est un processeur spécialisé dans le calcul graphique, conçu pour accélérer le rendu d'images et de vidéos en effectuant des opérations parallèles."),
        Question(50562, "Quel est le langage de base de données?", listOf("Python", "SQL", "C++", "Java"), 1, "Tech", Difficulty.MEDIUM, explanation = "SQL, pour Structured Query Language, est le langage standard utilisé pour interroger et gérer les bases de données relationnelles."),
        Question(50563, "Qu'est-ce que le JSON?", listOf("Un type de serveur", "Un format de données léger", "Un langage de programmation", "Un protocole réseau"), 1, "Tech", Difficulty.MEDIUM, explanation = "JSON, pour JavaScript Object Notation, est un format texte structuré et facile à lire, utilisé pour échanger des données entre applications, notamment sur le web."),
        Question(50564, "Quel est le nombre de transistors dans une puce moderne?", listOf("Des millions", "Des milliards", "Des trillions", "Des millions seulement"), 1, "Tech", Difficulty.HARD, explanation = "La loi de Moore a permis de miniaturiser les transistors, et les processeurs modernes comme l'Apple M2 Ultra en contiennent plus de 100 milliards."),
        Question(50565, "Qu'est-ce que le NoSQL?", listOf("Un type de serveur", "Une base de données non relationnelle", "Un langage de programmation", "Un protocole réseau"), 1, "Tech", Difficulty.HARD, explanation = "Le terme NoSQL désigne les bases de données qui n'utilisent pas le modèle relationnel classique (tables et SQL), privilégiant des structures flexibles comme les documents ou les graphes pour gérer de grands volumes de données."),
        Question(50566, "Quel est le créateur de YouTube?", listOf("Bill Gates", "Steve Jobs", "Steve Chen et Chad Hurley", "Jack Ma"), 2, "Tech", Difficulty.MEDIUM, explanation = "YouTube a été fondé en 2005 par Steve Chen, Chad Hurley et Jawed Karim, d'anciens employés de PayPal."),
        Question(50567, "Qu'est-ce que le responsive design?", listOf("Un langage de programmation", "Un design web adapté à tous les appareils", "Un type de serveur", "Un protocole réseau"), 1, "Tech", Difficulty.MEDIUM, explanation = "Le responsive design permet à un site web de s'adapter automatiquement à la taille de l'écran (ordinateur, tablette, smartphone) grâce à des grilles flexibles et des requêtes CSS."),
        Question(50568, "Quel est le nombre de bits dans un byte?", listOf("4", "8", "16", "32"), 1, "Tech", Difficulty.EASY, explanation = "Un byte est composé de 8 bits, une convention standardisée dans l'informatique pour représenter un caractère ou une donnée élémentaire."),
        Question(50569, "Qu'est-ce que le Wi-Fi?", listOf("Un câble de connexion", "Une technologie de connexion sans fil", "Un type de serveur", "Un langage de programmation"), 1, "Tech", Difficulty.EASY, explanation = "Le Wi-Fi permet à des appareils électroniques d'échanger des données par ondes radio, évitant ainsi les câbles physiques."),
        Question(50570, "Quel est le standard pour les appareils mobiles Bluetooth?", listOf("802.11", "802.15", "802.3", "802.16"), 1, "Tech", Difficulty.HARD, explanation = "Le standard 802.15 est défini par l’IEEE pour les réseaux sans fil à courte portée, comme le Bluetooth, utilisé dans les appareils mobiles pour la communication entre périphériques."),
        Question(50571, "Qu'est-ce que la virtualisation?", listOf("Un jeu vidéo", "La création de versions virtuelles d'environnements informatiques", "Un type de serveur", "Un langage de programmation"), 1, "Tech", Difficulty.HARD, explanation = "La virtualisation permet d'exécuter plusieurs systèmes d'exploitation ou applications sur un seul serveur physique, en créant des environnements isolés via un hyperviseur."),
        Question(50572, "Quel est le fondateur de Amazon?", listOf("Bill Gates", "Steve Jobs", "Jeff Bezos", "Jack Ma"), 2, "Tech", Difficulty.EASY, explanation = "Jeff Bezos a fondé Amazon en 1994, initialement comme une librairie en ligne, avant d'en faire un géant mondial du commerce électronique et du cloud computing."),
        Question(50573, "Qu'est-ce que le cache?", listOf("Un type de serveur", "Une mémoire rapide stockant les données fréquemment accédées", "Un langage de programmation", "Un protocole réseau"), 1, "Tech", Difficulty.HARD, explanation = "Le cache est une mémoire à haute vitesse qui conserve temporairement des copies de données souvent utilisées, afin d'accélérer leur accès par le processeur ou le navigateur."),
        Question(50574, "Quel langage de programmation minimaliste et concurrent a ete cree par Google en 2009 ?", listOf("Java", "Go", "Python", "C++"), 1, "Tech", Difficulty.MEDIUM, explanation = "Go a été conçu par Google en 2009 pour combiner performance, simplicité et support natif de la concurrence, répondant aux besoins des systèmes modernes."),
        Question(50575, "Qu'est-ce que le crawling?", listOf("Un jeu vidéo", "L'exploration automatique de pages web par les moteurs de recherche", "Un type de serveur", "Un langage de programmation"), 1, "Tech", Difficulty.HARD, explanation = "Le crawling est le processus par lequel les moteurs de recherche comme Google parcourent automatiquement le web à l'aide de robots pour indexer le contenu des pages."),
        Question(50576, "Quel est le protocole de transfert de fichiers sécurisé?", listOf("FTP", "SFTP", "HTTP", "SMTP"), 1, "Tech", Difficulty.MEDIUM, explanation = "SFTP (SSH File Transfer Protocol) chiffre les données via SSH, contrairement à FTP qui les envoie en clair, offrant ainsi une sécurité accrue pour les transferts de fichiers."),
        Question(50577, "Qu'est-ce qu'un framework?", listOf("Un type de serveur", "Une structure logicielle pour développer des applications", "Un langage de programmation", "Un protocole réseau"), 1, "Tech", Difficulty.MEDIUM, explanation = "Un framework fournit une base structurée avec des outils et des conventions prédéfinis, permettant aux développeurs de gagner du temps en évitant de réinventer la roue pour des tâches courantes."),
        Question(50578, "Quel est le créateur de Wikipedia?", listOf("Bill Gates", "Jimmy Wales", "Steve Jobs", "Mark Zuckerberg"), 1, "Tech", Difficulty.MEDIUM, explanation = "Jimmy Wales a fondé Wikipedia en 2001, avec Larry Sanger, pour créer une encyclopédie libre et collaborative accessible à tous."),
        Question(50579, "Qu'est-ce que le SEO?", listOf("Search Engine Operator", "Search Engine Optimization", "System Entry Optimization", "Search Entry Operator"), 1, "Tech", Difficulty.MEDIUM, explanation = "Le SEO désigne l'ensemble des techniques visant à optimiser la visibilité d'un site web dans les résultats des moteurs de recherche."),
        Question(50580, "Quel est le nombre de gigabytes dans un terabyte?", listOf("100", "512", "1000", "1024"), 3, "Tech", Difficulty.EASY, explanation = "Un terabyte équivaut à 1024 gigabytes car le stockage numérique utilise le système binaire, où chaque unité est multipliée par 1024 (2^10) plutôt que par 1000."),
        Question(50581, "Qu'est-ce que DevOps?", listOf("Un jeu vidéo", "Une approche combinant développement et opérations informatiques", "Un type de serveur", "Un langage de programmation"), 1, "Tech", Difficulty.HARD, explanation = "DevOps est une méthodologie qui intègre les équipes de développement et d'exploitation pour améliorer la collaboration et automatiser les processus de livraison logicielle."),
        Question(50582, "Quel est le fondateur de Twitter?", listOf("Mark Zuckerberg", "Jack Dorsey", "Steve Jobs", "Evan Williams"), 1, "Tech", Difficulty.MEDIUM, explanation = "Jack Dorsey a cofondé Twitter en 2006, en concevant l'idée d'une plateforme de microblogging limitée à 140 caractères."),
        Question(50583, "Qu'est-ce que le DOM?", listOf("Document Object Model", "Digital Operating Module", "Dynamic Object Management", "Data Object Method"), 0, "Tech", Difficulty.HARD, explanation = "Le DOM est une interface de programmation qui représente la structure d'un document HTML ou XML sous forme d'arbre d'objets, permettant aux scripts de modifier dynamiquement le contenu, la structure et le style d'une page web."),
        Question(50584, "Quel est le nombre maximum de connexions TCP simultanées?", listOf("256", "1024", "65536", "1000000"), 2, "Tech", Difficulty.EXPERT, explanation = "Le nombre maximum de connexions TCP simultanées est limité par le nombre de ports disponibles (16 bits), soit 65536 (de 0 à 65535). Cette limite théorique vient de la taille du champ de port source dans l'en-tête TCP."),
        Question(50585, "Qu'est-ce que le SaaS?", listOf("Software as a Service", "System as a Service", "Storage as a Service", "Server as a Service"), 0, "Tech", Difficulty.HARD, explanation = "Le SaaS désigne un modèle de distribution de logiciels où l'accès se fait via internet, sans installation locale. L'utilisateur paie un abonnement pour utiliser l'application hébergée par le fournisseur."),
        Question(50586, "Quel interpreteur de commandes est le shell par defaut sur la plupart des systemes Linux ?", listOf("Python", "Bash", "C++", "Java"), 1, "Tech", Difficulty.MEDIUM, explanation = "Bash (Bourne Again SHell) est le shell par défaut sur la plupart des distributions Linux car il succède au shell Bourne original tout en intégrant des fonctionnalités avancées."),
        Question(50587, "Qu'est-ce que Docker?", listOf("Un type de serveur", "Une plateforme de conteneurisation logicielle", "Un langage de programmation", "Un protocole réseau"), 1, "Tech", Difficulty.HARD, explanation = "Docker est un outil qui permet d'empaqueter des applications et leurs dépendances dans des conteneurs légers et portables, simplifiant le déploiement sur différents environnements."),
        Question(50588, "Quel est le système de gestion de versions le plus populaire?", listOf("Subversion", "Mercurial", "Git", "Perforce"), 2, "Tech", Difficulty.MEDIUM, explanation = "Git est devenu le standard de l'industrie pour le contrôle de versions, créé par Linus Torvalds en 2005 pour le développement du noyau Linux."),
        Question(50589, "Qu'est-ce que le phishing?", listOf("Un poisson d'eau douce", "Une tentative de fraude pour obtenir des informations sensibles", "Un type de serveur", "Un langage de programmation"), 1, "Tech", Difficulty.MEDIUM, explanation = "Le phishing est une technique d'ingénierie sociale où des fraudeurs envoient des emails ou messages imitant des entités légitimes pour voler mots de passe ou données bancaires."),
        Question(50590, "Quel est le nombre de processeurs logiques dans un i9 standard?", listOf("4", "8", "12", "16"), 3, "Tech", Difficulty.HARD, explanation = "Les processeurs Intel Core i9 standard de génération récente (comme la 12e et 13e) intègrent 8 cœurs physiques et 16 threads grâce à l'Hyper-Threading, ce qui donne 16 processeurs logiques."),
        Question(50591, "Qu'est-ce que OpenGL?", listOf("Un langage de programmation", "Une API pour la programmation graphique 3D", "Un système d'exploitation", "Un protocole réseau"), 1, "Tech", Difficulty.HARD, explanation = "OpenGL est une interface de programmation (API) standardisée et multiplateforme, utilisée pour le rendu de graphismes 2D et 3D, notamment dans les jeux vidéo et les applications de visualisation."),
        Question(50592, "Quel est le créateur de Slack?", listOf("Bill Gates", "Stewart Butterfield", "Steve Jobs", "Mark Zuckerberg"), 1, "Tech", Difficulty.HARD, explanation = "Stewart Butterfield a cofondé Slack en 2013, après avoir déjà créé Flickr, un site de partage de photos."),
        Question(50593, "Qu'est-ce que la concurrence en programmation?", listOf("Un jeu vidéo", "L'exécution simultanée de plusieurs tâches", "Un type de serveur", "Un langage de programmation"), 1, "Tech", Difficulty.HARD, explanation = "En programmation, la concurrence désigne la capacité d'un système à exécuter plusieurs tâches de manière entrelacée, donnant l'illusion d'une simultanéité sur un seul cœur."),
        Question(50594, "Quel est le protocole de voix sur IP?", listOf("VoIP", "SIP", "RTP", "All of the above"), 3, "Tech", Difficulty.HARD, explanation = "Le protocole de voix sur IP (VoIP) regroupe plusieurs protocoles comme SIP, H.323 ou RTP, qui assurent la transmission de la voix sur Internet."),
        Question(50595, "Qu'est-ce que RESTful?", listOf("Un type de serveur", "Un style architectural pour les API web", "Un langage de programmation", "Un protocole réseau"), 1, "Tech", Difficulty.HARD, explanation = "RESTful est un style d'architecture logicielle qui définit des contraintes pour créer des API web légères et évolutives, en utilisant les verbes HTTP standards comme GET, POST, PUT et DELETE."),
        Question(50596, "Quel est le créateur de Redis?", listOf("Bill Gates", "Salvatore Sanfilippo", "Steve Jobs", "Mark Zuckerberg"), 1, "Tech", Difficulty.EXPERT, explanation = "Salvatore Sanfilippo, connu sous le pseudonyme antirez, a créé Redis en 2009 pour améliorer les performances de son startup de logs en temps réel."),
        Question(50597, "Qu'est-ce que SOLID dans la programmation?", listOf("Un type de serveur", "Un ensemble de principes de conception logicielle", "Un langage de programmation", "Un protocole réseau"), 1, "Tech", Difficulty.EXPERT, explanation = "SOLID est un acronyme pour cinq principes de conception orientée objet (responsabilité unique, ouvert/fermé, substitution de Liskov, ségrégation d'interfaces, inversion de dépendances) visant à rendre le code plus maintenable et évolutif."),
        Question(50598, "Quel est le nombre de noyaux dans un processeur Ryzen 9?", listOf("8", "12", "16", "32"), 2, "Tech", Difficulty.HARD, explanation = "Le Ryzen 9 est le haut de gamme grand public d'AMD, et son modèle phare, le 7950X, embarque 16 cœurs physiques pour des performances maximales en calcul lourd."),
        Question(50599, "Qu'est-ce que WebAssembly?", listOf("Un type de serveur", "Un format binaire pour l'exécution de code dans les navigateurs", "Un langage de programmation", "Un protocole réseau"), 1, "Tech", Difficulty.EXPERT, explanation = "WebAssembly est un format d'instructions binaires conçu pour être exécuté à grande vitesse dans les navigateurs web, permettant d'exécuter du code compilé depuis des langages comme C, C++ ou Rust."),
        Question(50600, "Quel est le fondateur de Nvidia?", listOf("Bill Gates", "Jensen Huang", "Steve Jobs", "Mark Zuckerberg"), 1, "Tech", Difficulty.HARD, explanation = "Jensen Huang a cofondé Nvidia en 1993 avec Chris Malachowsky et Curtis Priem, et en est le PDG depuis sa création.")
    )

    private fun nature(): List<Question> = listOf(
        // ===== NATURE (75 questions) =====
        Question(50601, "Quel est l'animal terrestre le plus rapide?", listOf("Girafe", "Antilope", "Guépard", "Cheval"), 2, "Nature", Difficulty.EASY, explanation = "Le guépard peut atteindre 110 km/h en pointe, grâce à sa colonne vertébrale flexible et ses griffes non rétractiles qui lui offrent une adhérence maximale."),
        Question(50602, "Combien de pattes a une araignée?", listOf("6", "8", "10", "4"), 1, "Nature", Difficulty.EASY, explanation = "Les araignées appartiennent à la classe des arachnides, qui se distinguent des insectes par huit pattes, contre six pour ces derniers."),
        Question(50603, "Quel est le plus grand océan du monde?", listOf("Atlantique", "Indien", "Arctique", "Pacifique"), 3, "Nature", Difficulty.EASY, explanation = "L'océan Pacifique est le plus vaste et le plus profond des océans, couvrant environ un tiers de la surface terrestre."),
        Question(50604, "Quel est l'animal qui vit le plus longtemps?", listOf("Éléphant", "Baleine", "Tortue", "Perroquet"), 2, "Nature", Difficulty.EASY, explanation = "Certaines tortues géantes, comme celle des Galápagos, peuvent vivre plus de 150 ans, ce qui en fait les vertébrés terrestres les plus longévifs."),
        Question(50605, "Combien de pattes a un insecte?", listOf("4", "6", "8", "10"), 1, "Nature", Difficulty.EASY, explanation = "Les insectes appartiennent à la classe des hexapodes, ce qui signifie qu'ils possèdent six pattes, réparties en trois paires sur le thorax."),
        Question(50607, "Quel est l'animal marin le plus grand?", listOf("Requin blanc", "Baleine bleue", "Poulpe géant", "Rorqual"), 1, "Nature", Difficulty.EASY, explanation = "La baleine bleue est le plus grand animal marin, pouvant atteindre 30 mètres de long et peser jusqu'à 200 tonnes."),
        Question(50608, "Combien de continents existe-t-il?", listOf("5", "6", "7", "8"), 2, "Nature", Difficulty.EASY, explanation = "Le modèle des sept continents (Afrique, Amérique du Nord, Amérique du Sud, Antarctique, Asie, Europe, Océanie) est le plus couramment enseigné dans les pays francophones."),
        Question(50609, "Quel est le gaz principal de l'atmosphère terrestre?", listOf("Oxygène", "Azote", "Argon", "Dioxyde de carbone"), 1, "Nature", Difficulty.EASY, explanation = "L'azote constitue environ 78 % de l'atmosphère terrestre, bien devant l'oxygène (21 %) et les autres gaz."),
        Question(50610, "Quel est l'arbre le plus haut du monde?", listOf("Chêne", "Séquoia", "Sapin", "Mélèze"), 1, "Nature", Difficulty.EASY, explanation = "Le séquoia géant de Californie, comme l'Hypérion, peut dépasser 115 mètres de hauteur, ce qui en fait l'espèce d'arbre la plus haute jamais mesurée."),
        Question(50613, "Qu'est-ce qu'une photosynthèse?", listOf("Un type de respiration", "Un processus de transformation de la lumière en énergie par les plantes", "Un type de mouvement", "Un processus digestif"), 1, "Nature", Difficulty.MEDIUM, explanation = "La photosynthèse permet aux plantes de convertir l'énergie lumineuse du soleil en énergie chimique, utilisée pour leur croissance, via la chlorophylle."),
        Question(50614, "Quel est le plus grand récif de corail du monde?", listOf("Récif de Ningaloo", "Récif de Belize", "Grande Barrière de Corail", "Récif d'Egypte"), 2, "Nature", Difficulty.MEDIUM, explanation = "La Grande Barrière de Corail, située au large de l'Australie, s'étend sur plus de 2 300 kilomètres et est visible depuis l'espace."),
        Question(50615, "Combien d'espèces d'oiseaux existe-t-il sur Terre?", listOf("500", "1000", "5000", "10000"), 2, "Nature", Difficulty.MEDIUM, explanation = "On estime qu'il existe environ 10 000 espèces d'oiseaux dans le monde, et non 5 000."),
        Question(50616, "Quel est le plus grand lac du monde?", listOf("Lac Baïkal", "Lac Tanganyika", "Mer Caspienne", "Lac Victoria"), 2, "Nature", Difficulty.MEDIUM, explanation = "La mer Caspienne est considérée comme le plus grand lac du monde en superficie, bien qu'elle soit salée et souvent appelée mer en raison de sa taille. Elle s'étend sur environ 371 000 km²."),
        Question(50617, "Combien de pattes a un crabe?", listOf("6", "8", "10", "12"), 2, "Nature", Difficulty.EASY, explanation = "Les crabes sont des crustacés décapodes, ce qui signifie qu'ils possèdent dix pattes au total. Cependant, la première paire est transformée en pinces, laissant huit pattes locomotrices."),
        Question(50618, "Quel est le mammifère marin le plus grand?", listOf("Requin blanc", "Baleine bleue", "Baleine grise", "Narval"), 1, "Nature", Difficulty.EASY, explanation = "La baleine bleue est le plus grand mammifère marin, atteignant jusqu'à 30 mètres de long et pesant plus de 170 tonnes. Elle détient le record de l'animal le plus massif ayant jamais existé sur Terre."),
        Question(50619, "Combien de dents a un crocodile?", listOf("60", "80", "100", "120"), 2, "Nature", Difficulty.MEDIUM, explanation = "Les crocodiles possèdent environ 100 dents, qui sont régulièrement remplacées tout au long de leur vie."),
        Question(50621, "Quel est le plus profond océan?", listOf("Atlantique", "Indien", "Pacifique", "Arctique"), 2, "Nature", Difficulty.MEDIUM, explanation = "La fosse des Mariannes, située dans l'océan Pacifique, atteint environ 11 000 mètres de profondeur, ce qui en fait l'océan le plus profond du monde."),
        Question(50622, "Quel est l'animal terrestre le plus lourd?", listOf("Rhinocéros", "Hippopotame", "Giraffe", "Éléphant"), 3, "Nature", Difficulty.MEDIUM, explanation = "L'éléphant d'Afrique, avec un poids pouvant atteindre 6 à 7 tonnes, est le plus lourd mammifère terrestre vivant."),
        Question(50623, "Quel est le plus long fleuve du monde?", listOf("Amazone", "Nil", "Yangtze", "Mississippi"), 1, "Nature", Difficulty.EASY, explanation = "Le Nil est généralement considéré comme le plus long fleuve du monde avec environ 6 650 km, bien que des débats existent avec l’Amazone selon les mesures."),
        Question(50624, "Combien de pattes a une mouche?", listOf("4", "6", "8", "10"), 1, "Nature", Difficulty.EASY, explanation = "Les insectes, comme la mouche, ont six pattes, ce qui les distingue des arachnides qui en ont huit."),
        Question(50626, "Quel est l'animal qui peut courir le plus vite?", listOf("Guépard", "Antilope pronghorn", "Autruche", "Lion"), 0, "Nature", Difficulty.HARD, explanation = "Le guépard peut atteindre des pointes à 110 km/h grâce à sa colonne vertébrale flexible et ses griffes non rétractiles qui offrent une adhérence maximale."),
        Question(50627, "Combien de fleuves coulent du Mont-Blanc?", listOf("1", "2", "3", "4"), 2, "Nature", Difficulty.HARD, explanation = "Le Mont-Blanc est le point de départ de trois fleuves majeurs : l'Arve, l'Isère et le Rhône, qui prennent leur source dans ses glaciers."),
        Question(50628, "Quel est le plus haut arbre du monde?", listOf("Séquoia", "Épicéa de Sitka", "Sapin de Douglas", "Mélèze"), 0, "Nature", Difficulty.HARD, explanation = "Le séquoia géant de Californie, nommé Hyperion, atteint 115,5 mètres de haut, ce qui en fait l'arbre le plus grand du monde."),
        Question(50630, "Quel est le plus grand marécage du monde?", listOf("Everglades", "Pantanal", "Sudd", "Delta de l'Okavango"), 1, "Nature", Difficulty.HARD, explanation = "Le Pantanal, situé principalement au Brésil, s'étend sur plus de 150 000 km², ce qui en fait la plus vaste zone humide de la planète."),
        Question(50631, "Quel est le plus long canyon du monde?", listOf("Canyon du Colorado", "Canyon de Colca", "Canyon du Yarlung Tsangpo", "Canyon de Bryce"), 2, "Nature", Difficulty.HARD, explanation = "Le canyon du Yarlung Tsangpo, au Tibet, mesure environ 500 kilomètres, dépassant le Grand Canyon des États-Unis en longueur."),
        Question(50632, "Quel est l'animal avec le plus long cou?", listOf("Girafe", "Autruche", "Cygne", "Alpaca"), 0, "Nature", Difficulty.EASY, explanation = "Avec un cou pouvant atteindre 2,4 mètres, la girafe détient le record du plus long cou parmi tous les animaux terrestres. Cette adaptation lui permet de brouter les feuilles en hauteur dans les savanes africaines."),
        Question(50633, "Combien de vertèbres a une girafe?", listOf("5", "7", "9", "11"), 1, "Nature", Difficulty.HARD, explanation = "Comme la plupart des mammifères, y compris les humains, la girafe possède sept vertèbres cervicales, mais chacune est très allongée pour lui donner son long cou."),
        Question(50635, "Quel est l'animal ayant la plus grande gueule?", listOf("Requin blanc", "Crocodile", "Hippopotame", "Hippocampe"), 2, "Nature", Difficulty.HARD, explanation = "L'hippopotame possède la plus grande gueule parmi les mammifères terrestres, avec une ouverture pouvant atteindre 1,2 mètre. Cette adaptation lui permet de brouter efficacement et d'intimider les prédateurs."),
        Question(50636, "Quel est le plus haut volcano du monde?", listOf("Mont Kilimanjaro", "Ojos del Salado", "Nevado Sajama", "Cotopaxi"), 1, "Nature", Difficulty.HARD, explanation = "L'Ojos del Salado, situé à la frontière entre le Chili et l'Argentine, culmine à 6 893 mètres, ce qui en fait le plus haut volcan actif du monde."),
        Question(50637, "Quel est le plus grand récif de corail?", listOf("Récif de Ningaloo", "Grande Barrière de Corail", "Palau", "Récif de Mesoamerican"), 1, "Nature", Difficulty.EASY, explanation = "La Grande Barrière de Corail, située au large de l'Australie, s'étend sur plus de 2 300 kilomètres et est visible depuis l'espace."),
        Question(50638, "Quel est l'animal le plus venimeux au monde?", listOf("Serpent coral", "Grenouille empoisonnée", "Méduse boîte", "Araignée brazilian wandering"), 3, "Nature", Difficulty.HARD, explanation = "L'araignée brésilienne errante détient le record de venin le plus toxique pour l'homme, selon le Livre Guinness des records. Son venin neurotoxique peut provoquer une paralysie respiratoire mortelle."),
        Question(50639, "Quel est le plus grand mammifère volant?", listOf("Chauve-souris bouledogue", "Renard volant", "Chauve-souris géante des Philippines", "Mégachauves-souris"), 2, "Nature", Difficulty.HARD, explanation = "La chauve-souris géante des Philippines, aussi appelée renard volant géant, détient le record du plus grand mammifère volant avec une envergure d'ailes pouvant atteindre 1,7 mètre."),
        Question(50640, "Quel est le plus grand oiseau du monde?", listOf("Autruche", "Émeu", "Casoar", "Nandou"), 0, "Nature", Difficulty.EASY, explanation = "L'autruche, qui peut mesurer jusqu'à 2,70 mètres et peser 150 kg, est l'oiseau le plus grand et le plus lourd actuellement vivant sur Terre."),
        Question(50641, "Quel est l'animal qui a le plus de dents?", listOf("Requin", "Narval", "Hippopotame", "Crocodile"), 0, "Nature", Difficulty.HARD, explanation = "Le requin possède plusieurs rangées de dents qui se renouvellent en continu, pouvant atteindre jusqu'à 3 000 dents au cours de sa vie."),
        Question(50643, "Quel est l'animal qui voit le plus loin?", listOf("Aigle", "Faucon", "Hibou", "Vautour"), 1, "Nature", Difficulty.HARD, explanation = "Le faucon pèlerin possède une acuité visuelle exceptionnelle, lui permettant de repérer une proie à plus d'un kilomètre de distance."),
        Question(50645, "Quel est l'animal qui saute le plus haut?", listOf("Kangourou", "Puce", "Cigale", "Grillon"), 1, "Nature", Difficulty.HARD, explanation = "La puce peut sauter jusqu'à 200 fois sa propre taille grâce à ses pattes arrière puissantes et une résine élastique dans ses articulations."),
        Question(50646, "Quel est le plus grand serpent du monde?", listOf("Anaconda", "Python réticulé", "Boa constrictor", "Cobra royal"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le python réticulé peut atteindre plus de 7 mètres de long, ce qui en fait le serpent le plus long du monde, dépassant l'anaconda vert en longueur."),
        Question(50647, "Quel est l'animal avec le plus grand cerveau?", listOf("Baleine bleue", "Éléphant", "Dauphin", "Humain"), 0, "Nature", Difficulty.MEDIUM, explanation = "La baleine bleue est le plus grand animal vivant sur Terre, et son cerveau pèse en moyenne 6 à 7 kilogrammes, ce qui en fait le plus volumineux de tous les animaux."),
        Question(50649, "Quel est l'animal ayant le plus grand rapport cerveau-corps?", listOf("Chimpanzé", "Perroquet", "Dauphin", "Baleine bleue"), 1, "Nature", Difficulty.HARD, explanation = "Le perroquet possède un cerveau volumineux par rapport à sa taille corporelle, ce qui lui confère des capacités cognitives avancées comme l'imitation vocale et la résolution de problèmes."),
        Question(50650, "Quel est le plus grand amphithéâtre naturel du monde?", listOf("Canyon du Colorado", "Vallée de la Mort", "Parc de Zhangjiajie", "Parc d'Arches"), 2, "Nature", Difficulty.EXPERT, explanation = "Le parc national de Zhangjiajie, en Chine, est célèbre pour ses piliers de grès karstiques, dont la formation géologique a créé un amphithéâtre naturel grandiose."),
        Question(50651, "Quel est l'animal le plus rapide en natation?", listOf("Dauphin", "Espadon", "Requin blanc", "Thon bleu"), 3, "Nature", Difficulty.HARD, explanation = "Le thon bleu peut atteindre des pointes de vitesse allant jusqu'à 70 km/h en nageant, grâce à sa forme hydrodynamique et ses muscles puissants."),
        Question(50652, "Quel est le plus grand papillon du monde?", listOf("Papillon Oiseau", "Papillon Atlas", "Papillon Morpho", "Papillon Sphinx"), 0, "Nature", Difficulty.HARD, explanation = "Le papillon oiseau, ou Ornithoptera alexandrae, est le plus grand papillon du monde avec une envergure pouvant atteindre 28 centimètres. Il vit en Papouasie-Nouvelle-Guinée."),
        Question(50653, "Quel est l'animal qui plonge le plus profond?", listOf("Baleine à bec", "Cachalot", "Phoque de Weddell", "Manchot empereur"), 1, "Nature", Difficulty.HARD, explanation = "Le cachalot peut plonger jusqu'à 3 000 mètres de profondeur pour chasser des calmars géants, ce qui en fait le mammifère plongeant le plus profondément."),
        Question(50654, "Quel est le plus grand cratère du monde?", listOf("Cratère d'Vredefort", "Cratère de Sudbury", "Cratère de Chicxulub", "Cratère de Manicouagan"), 0, "Nature", Difficulty.EXPERT, explanation = "Le cratère d'Vredefort, en Afrique du Sud, est le plus grand cratère d'impact connu sur Terre, avec un diamètre d'environ 300 kilomètres. Il s'est formé il y a plus de deux milliards d'années suite à la collision d'une météorite."),
        Question(50655, "Quel est l'animal le plus vieux?", listOf("Tortue géante", "Baleine de Groenland", "Requin du Groenland", "Éponge de verre"), 2, "Nature", Difficulty.EXPERT, explanation = "Le requin du Groenland peut vivre plus de 400 ans, ce qui en fait le vertébré le plus longévif connu, grâce à son métabolisme extrêmement lent dans les eaux froides arctiques."),
        Question(50656, "Quel est le plus grand système de cavernes du monde?", listOf("Système de cavernes de Mammoth", "Son Doong Cave", "Grotte de Chiquibul", "Grotte de Mulu"), 0, "Nature", Difficulty.EXPERT, explanation = "Le système de Mammoth, situé dans le Kentucky aux États-Unis, détient le record avec plus de 676 kilomètres de passages cartographiés."),
        Question(50657, "Quel est l'animal ayant le plus long cœur?", listOf("Éléphant", "Giraffe", "Cachalot", "Baleine bleue"), 3, "Nature", Difficulty.EXPERT, explanation = "Le cœur de la baleine bleue peut peser jusqu'à 600 kilos, ce qui en fait le plus grand et le plus lourd de tous les animaux."),
        Question(50658, "Quel est le plus grand jardin botanique du monde?", listOf("Kew Gardens", "New York Botanical Garden", "Royal Botanic Garden Sydney", "Singapour Botanic Gardens"), 0, "Nature", Difficulty.HARD, explanation = "Kew Gardens, situé à Londres, possède la plus vaste collection de plantes vivantes au monde, avec plus de 50 000 espèces, ce qui en fait le plus grand jardin botanique."),
        Question(50659, "Quel est l'animal qui a la plus longue queue?", listOf("Girafe", "Léopard", "Lion", "Raton laveur"), 1, "Nature", Difficulty.MEDIUM, explanation = "Le léopard possède une queue particulièrement longue, mesurant jusqu'à 110 cm, qui lui sert d'équilibreur lors des sauts et des déplacements dans les arbres."),
        Question(50660, "Quel est le plus grand bâtiment naturel du monde?", listOf("Grand Canyon", "Château de Dracula", "Grottes de Carlsbad", "Parc de Zhangjiajie"), 0, "Nature", Difficulty.EXPERT, explanation = "Le Grand Canyon, situé en Arizona, est considéré comme le plus grand canyon du monde avec ses 446 kilomètres de long et ses 1 800 mètres de profondeur.")
    )

    private fun mythologie(): List<Question> = listOf(
        // ===== MYTHOLOGIE (75 questions) =====
        Question(50661, "Quel est le roi des dieux dans la mythologie grecque?", listOf("Poséidon", "Arès", "Zeus", "Hadès"), 2, "Mythologie", Difficulty.EASY, explanation = "Zeus est le dieu du ciel et de la foudre, et il a renversé son père Cronos pour devenir le souverain de l'Olympe et le maître des dieux grecs."),
        Question(50662, "Quel dieu grec est le dieu de la mer?", listOf("Zeus", "Poséidon", "Hermès", "Apollon"), 1, "Mythologie", Difficulty.EASY, explanation = "Poséidon est l'un des douze dieux de l'Olympe, frère de Zeus et d'Hadès, et règne sur les océans, les tempêtes et les tremblements de terre, souvent représenté avec un trident."),
        Question(50663, "Quel est le dieu romain de la guerre?", listOf("Mars", "Mercure", "Neptune", "Vénus"), 0, "Mythologie", Difficulty.EASY, explanation = "Mars est l'équivalent romain du dieu grec Arès et préside à la guerre, mais aussi à l'agriculture, une dualité importante dans la culture romaine."),
        Question(50664, "Quel dieu est le dieu de la sagesse dans la mythologie grecque?", listOf("Aphrodite", "Athéna", "Héra", "Apollon"), 1, "Mythologie", Difficulty.EASY, explanation = "Athéna est la déesse de la sagesse, de la stratégie militaire et des arts, née de la tête de Zeus. Elle est souvent représentée avec une chouette, symbole de la sagesse."),
        Question(50665, "Quel est le dieu de la forge dans la mythologie grecque?", listOf("Arès", "Héphaïstos", "Poséidon", "Apollon"), 1, "Mythologie", Difficulty.EASY, explanation = "Héphaïstos, fils d'Héra et de Zeus, est le dieu grec du feu, de la forge et des artisans. Il fabriquait les armes des dieux et les éclairs de Zeus dans son atelier sous l'Olympe."),
        Question(50666, "Quel est le dieu des enfers dans la mythologie grecque?", listOf("Poséidon", "Hadès", "Zeus", "Arès"), 1, "Mythologie", Difficulty.EASY, explanation = "Hadès est le frère de Zeus et de Poséidon, et il règne sur le royaume des morts après le partage du monde entre les trois dieux."),
        Question(50667, "Qui est la déesse de l'amour dans la mythologie grecque?", listOf("Héra", "Aphrodite", "Athéna", "Artémis"), 1, "Mythologie", Difficulty.EASY, explanation = "Aphrodite, née de l'écume de la mer selon Hésiode, est la déesse grecque de l'amour, de la beauté et de la séduction."),
        Question(50668, "Quel dieu est le messager des dieux dans la mythologie grecque?", listOf("Apollon", "Hermès", "Arès", "Héphaistos"), 1, "Mythologie", Difficulty.EASY, explanation = "Hermès est le messager des dieux grecs, connu pour sa rapidité et son rôle de guide des âmes vers les Enfers."),
        Question(50669, "Qui est la reine des dieux dans la mythologie grecque?", listOf("Aphrodite", "Athéna", "Héra", "Artémis"), 2, "Mythologie", Difficulty.EASY, explanation = "Héra est la sœur et l'épouse de Zeus, roi des dieux, ce qui fait d'elle la reine de l'Olympe, déesse du mariage et de la famille."),
        Question(50670, "Quel dieu est le dieu du soleil dans la mythologie grecque?", listOf("Apollon", "Zeus", "Hermès", "Arès"), 0, "Mythologie", Difficulty.EASY, explanation = "Apollon est le dieu du soleil, de la musique et de la poésie dans la mythologie grecque, souvent représenté avec un char solaire traversant le ciel."),
        Question(50671, "Qui a vaincu le Minotaure dans la mythologie grecque?", listOf("Persée", "Thésée", "Achille", "Héraclès"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Thésée a tué le Minotaure dans le labyrinthe de Crète, aidé par le fil d'Ariane pour retrouver son chemin."),
        Question(50672, "Quel est le labeur impossible demandé à Héraclès?", listOf("Capturer la Biche de Cérynie", "Tuer l'Hydre de Lerne", "Obtenir les pommes d'or des Hespérides", "Ramener Cerbère du monde souterrain"), 2, "Mythologie", Difficulty.MEDIUM, explanation = "Ce travail était considéré comme impossible car les Hespérides, gardiennes du jardin, étaient protégées par un dragon immortel, et Héraclès ne connaissait pas l'emplacement du jardin."),
        Question(50673, "Combien de travaux Héraclès a-t-il dû accomplir?", listOf("6", "12", "10", "15"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Héraclès a dû accomplir douze travaux, initialement dix, mais deux furent invalidés par Eurysthée, portant le total à douze."),
        Question(50674, "Qui est le Titan du temps dans la mythologie grecque?", listOf("Cronos", "Océanos", "Japet", "Thémis"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, Cronos est le Titan du temps, célèbre pour avoir détrôné son père Ouranos et régné pendant l'âge d'or avant d'être vaincu par son fils Zeus."),
        Question(50675, "Quel est le nom du monde souterrain dans la mythologie grecque?", listOf("Élysée", "Tartare", "Hadès", "Enfer"), 2, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, le royaume des morts porte le nom de son dieu souverain, Hadès, qui règne sur les enfers souterrains."),
        Question(50676, "Qui a créé Pandore dans la mythologie grecque?", listOf("Zeus", "Héphaïstos", "Athéna", "Apollon"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, c'est Zeus qui ordonna la création de Pandore, la première femme, par Héphaïstos, comme punition envers l'humanité après le vol du feu par Prométhée."),
        Question(50677, "Quel est le nom du cheval de Troie dans la mythologie grecque?", listOf("Le Cheval noir", "Le Cheval de bois", "Le Cheval blanc", "Le Cheval d'or"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Le Cheval de bois est le nom donné à l'immense construction en bois utilisée par les Grecs pour s'introduire dans Troie, mettant fin à la guerre de Troie."),
        Question(50678, "Qui est la première femme humaine créée selon la mythologie grecque?", listOf("Héra", "Pandore", "Aphrodite", "Athéna"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Selon le mythe grec, Pandore fut créée par Héphaïstos sur ordre de Zeus pour punir l'humanité après que Prométhée lui ait offert le feu. Elle est célèbre pour avoir ouvert la boîte qui libéra tous les maux du monde."),
        Question(50679, "Quel est le nom du jardin des dieux immortels dans la mythologie grecque?", listOf("Olympe", "Élysée", "Tartare", "Hadès"), 0, "Mythologie", Difficulty.HARD, explanation = "L'Olympe est la demeure des dieux grecs, un sommet montagneux où ils vivent éternellement, et non un jardin."),
        Question(50680, "Qui est le père de Méduse dans la mythologie grecque?", listOf("Poséidon", "Zeus", "Hadès", "Cronos"), 0, "Mythologie", Difficulty.HARD, explanation = "Dans la plupart des récits, Méduse est l'une des trois Gorgones, filles des divinités marines Phorcys et Céto. Poséidon est souvent mentionné comme son amant, mais il n'est pas son père."),
        Question(50681, "Quel est le nom de l'arme magique de Zeus?", listOf("Trident", "Foudre", "Épée", "Bouclier"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Dans la mythologie grecque, le foudre est l'arme forgée par les Cyclopes que Zeus utilise pour affirmer son autorité sur les dieux et les hommes."),
        Question(50682, "Qui a vaincu Méduse dans la mythologie grecque?", listOf("Thésée", "Persée", "Héraclès", "Achille"), 1, "Mythologie", Difficulty.EASY, explanation = "Persée, fils de Zeus, a décapité Méduse en utilisant le bouclier poli d'Athéna pour éviter son regard pétrifiant."),
        Question(50683, "Quel est le nom du phoenix dans la mythologie égyptienne?", listOf("Benu", "Ra", "Thot", "Osiris"), 0, "Mythologie", Difficulty.HARD, explanation = "Le Benu est l'oiseau sacré de la mythologie égyptienne, associé au dieu solaire Rê et au cycle du soleil levant, préfigurant le phénix grec."),
        Question(50684, "Quel dieu égyptien est le dieu des morts?", listOf("Osiris", "Anubis", "Thot", "Horus"), 0, "Mythologie", Difficulty.MEDIUM, explanation = "Osiris est le dieu des morts dans la mythologie égyptienne, car il a été assassiné par son frère Seth puis ressuscité pour régner sur l'au-delà."),
        Question(50685, "Qui est la déesse égyptienne du ciel?", listOf("Isis", "Hathor", "Nut", "Sekhmet"), 2, "Mythologie", Difficulty.HARD, explanation = "Nut est la déesse égyptienne du ciel, souvent représentée comme une femme voûtée au-dessus de la Terre, son corps parsemé d'étoiles. Elle est la mère d'Osiris, Isis, Seth et Nephtys."),
        Question(50686, "Quel est le dieu du soleil dans la mythologie égyptienne?", listOf("Thot", "Ra", "Horus", "Amon"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Ra est le dieu solaire principal de la mythologie égyptienne, souvent représenté avec une tête de faucon surmontée d'un disque solaire. Il était considéré comme le créateur de l'univers et le souverain des dieux."),
        Question(50687, "Qui est le dieu scandinave du tonnerre?", listOf("Odin", "Thor", "Loki", "Freya"), 1, "Mythologie", Difficulty.EASY, explanation = "Thor est le dieu du tonnerre dans la mythologie nordique, fils d'Odin et protecteur de Midgard, connu pour son marteau Mjöllnir."),
        Question(50688, "Quel est le nom du mont des dieux dans la mythologie scandinave?", listOf("Valhalla", "Asgard", "Midgard", "Jotunheim"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Asgard est le royaume des dieux Ases dans la mythologie nordique, situé au sommet de l'arbre cosmique Yggdrasil."),
        Question(50689, "Qui est le père de tous les dieux dans la mythologie scandinave?", listOf("Thor", "Odin", "Loki", "Tyr"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Odin est considéré comme le père de tous les dieux dans la mythologie nordique, car il est le chef des Ases et le créateur du monde avec ses frères Vili et Vé."),
        Question(50690, "Quel dieu scandinave est le dieu du feu?", listOf("Odin", "Loki", "Thor", "Heimdall"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Loki est souvent associé au feu dans la mythologie nordique, bien qu'il soit plus précisément un dieu farceur, son nom étant lié au mot vieux norrois pour \"flamme\"."),
        Question(50691, "Quel est le nom du serpent qui ronge les racines de Yggdrasil dans la mythologie scandinave?", listOf("Jörmungandr", "Nidhogg", "Sköll", "Hati"), 1, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie nordique, Nidhogg est le serpent ou dragon qui ronge les racines d'Yggdrasil, l'arbre-monde, symbolisant la destruction et le chaos aux confins du cosmos."),
        Question(50692, "Qui est le dieu indien de la destruction?", listOf("Brahma", "Vishnou", "Shiva", "Ganesha"), 2, "Mythologie", Difficulty.MEDIUM, explanation = "Shiva est l'une des principales divinités de l'hindouisme, faisant partie de la Trimurti avec Brahma (créateur) et Vishnu (préservateur). Son rôle de destructeur permet la renaissance et la transformation du cosmos."),
        Question(50693, "Quel est le nom de la déesse mère hindoue?", listOf("Parvati", "Durga", "Shakti", "Kali"), 2, "Mythologie", Difficulty.HARD, explanation = "Shakti est la déesse mère suprême dans l'hindouisme, représentant l'énergie divine féminine et la force créatrice de l'univers."),
        Question(50694, "Quel dieu romain est équivalent à Zeus?", listOf("Mars", "Jupiter", "Neptune", "Mercure"), 1, "Mythologie", Difficulty.EASY, explanation = "Jupiter était le roi des dieux dans la mythologie romaine, assimilé au Zeus grec lors de la romanisation de la culture hellénistique."),
        Question(50695, "Quel dieu romain est équivalent à Poséidon?", listOf("Mars", "Jupiter", "Neptune", "Mercure"), 2, "Mythologie", Difficulty.EASY, explanation = "Neptune est le dieu romain des mers et des océans, directement assimilé au Poséidon grec lors de la romanisation de la mythologie hellénique."),
        Question(50696, "Quel dieu romain est équivalent à Hermès?", listOf("Mars", "Jupiter", "Neptune", "Mercure"), 3, "Mythologie", Difficulty.EASY, explanation = "Mercure est l'équivalent romain d'Hermès, dieu grec du commerce, des voyages et des messagers. Les Romains ont assimilé de nombreux dieux grecs en leur donnant des noms latins."),
        Question(50697, "Quel dieu romain est équivalent à Arès?", listOf("Mars", "Jupiter", "Neptune", "Vulcain"), 0, "Mythologie", Difficulty.EASY, explanation = "Mars est le dieu romain de la guerre, directement assimilé à Arès dans la mythologie grecque."),
        Question(50698, "Quel dieu romain est équivalent à Héphaïstos?", listOf("Mars", "Jupiter", "Vulcain", "Mercure"), 2, "Mythologie", Difficulty.MEDIUM, explanation = "Vulcain est le dieu romain du feu et de la forge, équivalent direct d'Héphaïstos dans la mythologie grecque."),
        Question(50699, "Quel est le nom du chien à trois têtes qui garde les enfers dans la mythologie grecque?", listOf("Orthus", "Cerbère", "Typhon", "Chimère"), 1, "Mythologie", Difficulty.EASY, explanation = "Cerbère est le chien monstrueux à trois têtes qui garde l'entrée des Enfers, empêchant les morts de s'en échapper et les vivants d'y pénétrer."),
        Question(50700, "Qui est le fils de Poséidon et de la nymphe Thétis?", listOf("Achille", "Ajax", "Hector", "Énée"), 0, "Mythologie", Difficulty.HARD, explanation = "Selon certaines versions de la mythologie grecque, Achille est le fils de Thétis, une nymphe de la mer, et non de Poséidon, mais plutôt du mortel Pélée. Cette confusion vient du lien de Thétis avec le monde marin, domaine de Poséidon."),
        Question(50701, "Quel est le nom de l'épée indestructible de Sigurd dans la mythologie scandinave?", listOf("Excalibur", "Grám", "Tyrfing", "Kusanagi"), 1, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie nordique, Grám est l'épée magique et indestructible forgée par le nain Regin, que Sigurd utilise pour tuer le dragon Fáfnir."),
        Question(50702, "Qui a forgé l'Anneau Unique dans les contes de la Terre du Milieu?", listOf("Morgoth", "Celebrimbor", "Sauron", "Saruman"), 2, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie de Tolkien, Sauron a forgé l'Anneau Unique en secret dans les flammes de la Montagne du Destin en Mordor pour asservir les peuples de la Terre du Milieu."),
        Question(50703, "Quel est le nom de la créature qui garde l'Arbre de la Vie dans la mythologie nordique?", listOf("Nidhogg", "Jörmungandr", "Sköll", "Hati"), 0, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie nordique, Nidhogg est un dragon ou serpent qui ronge les racines d'Yggdrasil, l'Arbre de Vie, symbolisant la destruction et le renouveau."),
        Question(50704, "Qui est le premier homme créé dans la mythologie grecque?", listOf("Prometheus", "Épiméthée", "Deucalion", "Prométhée"), 0, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie grecque, Prométhée a façonné le premier homme à partir d'argile et d'eau, puis lui a offert le feu, défiant ainsi Zeus."),
        Question(50705, "Quel Titan a volé le feu pour l'humanité?", listOf("Océanos", "Japet", "Prométhée", "Cronos"), 2, "Mythologie", Difficulty.EASY, explanation = "Prométhée a dérobé le feu aux dieux de l'Olympe pour le donner aux humains, défiant ainsi Zeus. Pour le punir, il fut enchaîné à un rocher où un aigle lui dévorait le foie chaque jour."),
        Question(50706, "Quel est le nom de la coupe sacrée dans la légende arthurienne?", listOf("Cauldron", "Saint Graal", "Calice", "Gobelet"), 1, "Mythologie", Difficulty.MEDIUM, explanation = "Le Saint Graal est la coupe utilisée par Jésus lors de la Cène, devenue un objet de quête mystique dans les récits du cycle arthurien."),
        Question(50707, "Qui est le roi légendaire britannique qui portait Excalibur?", listOf("Merlin", "Lancelot", "Arthur", "Guenevière"), 2, "Mythologie", Difficulty.EASY, explanation = "Excalibur est l'épée légendaire du roi Arthur, figure centrale des récits médiévaux de la Table Ronde et de la quête du Graal."),
        Question(50708, "Quel est le nom du magicien dans la légende arthurienne?", listOf("Mordred", "Merlin", "Gareth", "Bedivere"), 1, "Mythologie", Difficulty.EASY, explanation = "Merlin est le célèbre enchanteur et conseiller du roi Arthur, personnage central des légendes arthuriennes issues de la littérature médiévale."),
        Question(50709, "Qui est la reine des fées dans la légende arthurienne?", listOf("Guenièvre", "Morgane", "Viviane", "Guinevere"), 2, "Mythologie", Difficulty.HARD, explanation = "Dans la légende arthurienne, Viviane, aussi appelée la Dame du Lac, est la souveraine des fées et la protectrice d'Excalibur."),
        Question(50710, "Quel est le nom du cheval blanc du Roi Arthur?", listOf("Llamrei", "Kaliburn", "Escalibur", "Morvran"), 0, "Mythologie", Difficulty.HARD, explanation = "Llamrei est le nom de la jument blanche du Roi Arthur dans la légende arthurienne, souvent mentionnée dans les textes médiévaux gallois."),
        Question(50711, "Qui est le fils caché du Roi Arthur?", listOf("Lancelot", "Gareth", "Mordred", "Bedivere"), 2, "Mythologie", Difficulty.MEDIUM, explanation = "Mordred est le fils illégitime d'Arthur et de sa demi-sœur Morgane, conçu par tromperie. Sa naissance est souvent liée à la prophétie de la chute du royaume de Camelot."),
        Question(50712, "Quel est le nom du château du Roi Arthur?", listOf("Tintagel", "Avalon", "Camelot", "Badon"), 2, "Mythologie", Difficulty.MEDIUM, explanation = "Camelot est le château légendaire du roi Arthur, mentionné pour la première fois dans les romans de chevalerie du XIIe siècle, notamment par Chrétien de Troyes."),
        Question(50713, "Quel est le nom de l'île légendaire où Arthur se retira?", listOf("Avalon", "Atlantis", "Lemuria", "Mu"), 0, "Mythologie", Difficulty.EASY, explanation = "Dans la légende arthurienne, Avalon est l'île magique où le roi Arthur fut emmené après sa dernière bataille pour y être soigné, avant son éventuel retour."),
        Question(50714, "Qui a tué le dragon Fafnir dans la mythologie scandinave?", listOf("Beowulf", "Sigurd", "Starkad", "Halvdan"), 1, "Mythologie", Difficulty.HARD, explanation = "Sigurd, héros de la mythologie nordique, tua le dragon Fafnir avec son épée Gram après avoir creusé une fosse et l'avoir transpercé par en dessous."),
        Question(50715, "Quel dieu est le gardien du pont arc-en-ciel dans la mythologie scandinave?", listOf("Odin", "Thor", "Heimdall", "Tyr"), 2, "Mythologie", Difficulty.HARD, explanation = "Heimdall est le dieu gardien du Bifröst, le pont arc-en-ciel reliant Midgard à Asgard. Il possède une ouïe et une vue exceptionnelles pour surveiller l'arrivée des géants."),
        Question(50716, "Qui est le géant de feu dans la mythologie scandinave?", listOf("Loki", "Surt", "Ymir", "Thrym"), 1, "Mythologie", Difficulty.HARD, explanation = "Surt est le géant de feu qui, selon la mythologie nordique, doit mettre le feu au monde lors du Ragnarök, la fin des temps."),
        Question(50717, "Quel est le nom de la fin du monde dans la mythologie scandinave?", listOf("Götterdämmerung", "Ragnarok", "Yule", "Asgard"), 1, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie nordique, le Ragnarök désigne la série d'événements apocalyptiques incluant une grande bataille et la destruction du monde, suivie de sa renaissance."),
        Question(50718, "Qui a créé le monde à partir de son corps dans la mythologie scandinave?", listOf("Odin", "Loki", "Ymir", "Surtr"), 2, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie scandinave, le géant primordial Ymir est tué par Odin et ses frères, qui utilisent son corps pour façonner le monde : sa chair devient la terre, son sang les océans, et ses os les montagnes."),
        Question(50719, "Quel est le nom du loup qui dévore le soleil dans la mythologie scandinave?", listOf("Sköll", "Hati", "Jörmungandr", "Fenrir"), 0, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie nordique, Sköll est le loup qui poursuit le Soleil (Sól) et finira par le dévorer lors du Ragnarök."),
        Question(50720, "Quel dieu grec a été transformé en serpent?", listOf("Hermès", "Poséidon", "Hadès", "Arès"), 0, "Mythologie", Difficulty.HARD, explanation = "Dans la mythologie grecque, Hermès a été transformé en serpent pour échapper à un géant lors de la Gigantomachie.")
    )

    private fun gastronomie(): List<Question> = listOf(
        // ===== GASTRONOMIE (75 questions) =====
        Question(50721, "Quel est le plat national de la France?", listOf("Coq au vin", "Pot-au-feu", "Crêpes", "Bouillabaisse"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Le pot-au-feu est considéré comme le plat national français en raison de son histoire populaire et de sa présence dans toutes les régions, bien que la France n'ait pas de plat officiel."),
        Question(50722, "Quel est le plat national de l'Italie?", listOf("Pizza", "Pâtes", "Risotto", "Osso buco"), 0, "Gastronomie", Difficulty.EASY, explanation = "La pizza, notamment la margherita aux couleurs du drapeau italien, est reconnue mondialement comme le plat emblématique de l'Italie, originaire de Naples."),
        Question(50723, "Quel est le plat national de la Suisse?", listOf("Fondue", "Raclette", "Rösti", "Schnitzel"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "La fondue au fromage est souvent considérée comme le plat national suisse, bien que la Suisse n'ait pas de plat officiel, car elle symbolise la convivialité et les traditions alpines."),
        Question(50726, "Quel est le plat national du Japon?", listOf("Sushi", "Ramen", "Tempura", "Yakitori"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le sushi est considéré comme le plat national du Japon en raison de sa popularité mondiale et de son lien profond avec la culture culinaire japonaise, bien que d'autres plats comme le ramen ou le curry soient aussi très consommés."),
        Question(50728, "Quel est le plat national de l'Inde?", listOf("Tikka Masala", "Biryani", "Samosas", "Dhal"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Le Biryani est considéré comme le plat national de l'Inde en raison de sa popularité à travers le pays, mêlant riz, épices et viande ou légumes dans une préparation emblématique de la cuisine indienne."),
        Question(50729, "Quel est le plat national de la Grèce?", listOf("Moussaka", "Souvlaki", "Feta", "Salade grecque"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "La moussaka est un plat traditionnel grec à base d'aubergines, de viande hachée et de béchamel, souvent considéré comme le plat national du pays."),
        Question(50731, "Quel fromage français est le plus célèbre?", listOf("Camembert", "Roquefort", "Brie", "Comté"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "Le camembert, originaire de Normandie, est l’un des fromages les plus emblématiques de France, reconnu mondialement pour sa texture crémeuse et son goût distinctif."),
        Question(50732, "Quel vin français est le plus prestigieux?", listOf("Bordeaux", "Bourgogne", "Champagne", "Loire"), 2, "Gastronomie", Difficulty.HARD, explanation = "Le Champagne est souvent considéré comme le vin français le plus prestigieux en raison de son appellation d'origine contrôlée, de son histoire liée au luxe et aux célébrations, et de sa reconnaissance mondiale comme symbole d'excellence."),
        Question(50733, "Quel est le plat français le plus classique?", listOf("Crêpes", "Croissant", "Baguette", "Coq au vin"), 3, "Gastronomie", Difficulty.MEDIUM, explanation = "Le coq au vin est un ragoût de poulet mijoté dans du vin rouge, souvent associé à la cuisine française traditionnelle et rustique."),
        Question(50734, "Quel est le gâteau français le plus connu?", listOf("Mille-feuille", "Éclair", "Macaron", "Madeleine"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "L'éclair, avec sa pâte à choux et son glaçage, est un classique des pâtisseries françaises, reconnu mondialement pour sa simplicité et son élégance."),
        Question(50735, "Quel est le dessert français le plus traditionnel?", listOf("Tarte Tatin", "Crème brûlée", "Mousse au chocolat", "Profiteroles"), 0, "Gastronomie", Difficulty.HARD, explanation = "La tarte Tatin est un classique de la pâtisserie française, née par accident à la fin du XIXe siècle à l'hôtel Tatin de Lamotte-Beuvron, où les sœurs Tatin ont caramélisé des pommes avant de les recouvrir de pâte."),
        Question(50736, "Quel est le fromage Italien le plus célèbre?", listOf("Parmesan", "Mozzarella", "Gorgonzola", "Ricotta"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "La mozzarella est le fromage italien le plus célèbre grâce à sa polyvalence, notamment dans les pizzas et salades, et à sa production artisanale à base de lait de bufflonne."),
        Question(50737, "Quel est le jambon italien le plus célèbre?", listOf("Prosciutto de Parme", "Jambon de Bayonne", "Jambon de Ibérique", "Jambon de Serrano"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "Le Prosciutto di Parma est un jambon cru AOP produit exclusivement dans la région de Parme, en Italie, selon des méthodes traditionnelles. Sa renommée mondiale vient de sa texture fondante et de son goût délicatement salé."),
        Question(50738, "Quel est le plat espagnol le plus célèbre?", listOf("Gazpacho", "Paella", "Ratatouille", "Bouillabaisse"), 1, "Gastronomie", Difficulty.EASY, explanation = "La paella est originaire de la région de Valence et est traditionnellement préparée avec du riz, du safran et divers ingrédients comme des fruits de mer ou du poulet."),
        Question(50739, "Quel vin espagnol est le plus connu?", listOf("Rioja", "Tempranillo", "Albariño", "Sherry"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "Le Rioja est le vin espagnol le plus célèbre en raison de sa longue tradition viticole et de sa reconnaissance internationale, notamment pour ses rouges élevés en fûts de chêne."),
        Question(50740, "Quel est le plat grec le plus populaire?", listOf("Souvlaki", "Moussaka", "Feta", "Salade grecque"), 1, "Gastronomie", Difficulty.EASY, explanation = "La moussaka est un plat traditionnel grec à base d'aubergines, de viande hachée et de béchamel, souvent considéré comme le plus emblématique du pays."),
        Question(50741, "Quel est le restaurant français le plus prestigieux?", listOf("L'Astrance", "Le Jules Verne", "Chez Pannisset", "Mikado"), 0, "Gastronomie", Difficulty.HARD, explanation = "L'Astrance est un restaurant parisien triplement étoilé au guide Michelin, dirigé par le chef Pascal Barbot, reconnu pour sa cuisine inventive et raffinée."),
        Question(50742, "Quel est le chef français le plus célèbre actuellement?", listOf("Alain Ducasse", "Paul Bocuse", "Jacques Pépin", "Guy Savoy"), 0, "Gastronomie", Difficulty.HARD, explanation = "Alain Ducasse est le chef le plus étoilé au monde, avec 21 étoiles Michelin cumulées, et dirige des restaurants sur plusieurs continents."),
        Question(50743, "Quel est le plus ancien restaurant de Paris?", listOf("Le Grand Café", "Café Procope", "Maison Fuchsias", "Restaurant Ledoyen"), 1, "Gastronomie", Difficulty.HARD, explanation = "Le Café Procope, fondé en 1686, est considéré comme le plus ancien restaurant de Paris encore en activité."),
        Question(50744, "Quel est le guide gastronomique le plus réputé?", listOf("Zagat", "Michelin", "TripAdvisor", "Yelp"), 1, "Gastronomie", Difficulty.HARD, explanation = "Le Guide Michelin, créé en 1900 par les frères Michelin, est considéré comme la référence mondiale en gastronomie grâce à son système d'étoiles attribuées aux meilleurs restaurants."),
        Question(50745, "Combien d'étoiles Michelin peut avoir un restaurant?", listOf("1", "2", "3", "4"), 2, "Gastronomie", Difficulty.EASY, explanation = "Le guide Michelin attribue jusqu'à trois étoiles, un système créé en 1926 pour distinguer les meilleures tables. Trois étoiles signifient une cuisine exceptionnelle qui vaut le voyage."),
        Question(50746, "Quel est le plus grand marché alimentaire du monde?", listOf("Tsukiji", "Torvehallerne", "Rialto", "Warorot"), 0, "Gastronomie", Difficulty.HARD, explanation = "Le marché de Tsukiji à Tokyo, bien que son activité de gros ait été déplacée à Toyosu en 2018, reste historiquement le plus vaste marché alimentaire au monde par sa superficie et son volume de produits."),
        Question(50747, "Quel est le fruit le plus consommé au monde?", listOf("Banane", "Pomme", "Orange", "Pastèque"), 0, "Gastronomie", Difficulty.EASY, explanation = "La banane est le fruit le plus consommé au monde en volume, devant la pomme et l'orange, grâce à sa disponibilité toute l'année et son prix abordable dans de nombreux pays."),
        Question(50748, "Quel est le légume le plus consommé au monde?", listOf("Carotte", "Pomme de terre", "Tomate", "Oignon"), 2, "Gastronomie", Difficulty.MEDIUM, explanation = "La tomate est techniquement un fruit, mais elle est consommée comme un légume et utilisée dans de nombreuses cuisines du monde, notamment en sauces, soupes et salades."),
        Question(50749, "Quel est le nombre de variétés de fromage français?", listOf("200", "400", "600", "800"), 2, "Gastronomie", Difficulty.HARD, explanation = "La France compte officiellement environ 600 variétés de fromages, une diversité reconnue par le général de Gaulle qui disait qu'il est difficile de gouverner un pays avec 365 fromages, un nombre depuis largement dépassé."),
        Question(50750, "Quel est le fromage français qui sent le plus fort?", listOf("Roquefort", "Limburger", "Époisses", "Munster"), 2, "Gastronomie", Difficulty.HARD, explanation = "L'Époisses est un fromage à pâte molle et croûte lavée dont l'odeur puissante provient du lavage à l'eau-de-vie de marc pendant l'affinage."),
        Question(50751, "Quel est le plat que les Français mangent le plus?", listOf("Pâtes", "Riz", "Pommes de terre", "Pain"), 2, "Gastronomie", Difficulty.HARD, explanation = "Les pommes de terre sont l'aliment le plus consommé en France, notamment sous forme de frites, purée ou gratin, grâce à leur polyvalence et leur prix abordable."),
        Question(50752, "Quel est le dessert que les Français mangent le plus?", listOf("Mousse au chocolat", "Crème brûlée", "Yaourt", "Gâteau"), 2, "Gastronomie", Difficulty.HARD, explanation = "Le yaourt est le dessert le plus consommé en France, devant les fruits et les pâtisseries, grâce à son prix abordable, sa praticité et sa présence quotidienne dans les foyers."),
        Question(50753, "Quel est le type de pâtes le plus populaire en Italie?", listOf("Spaghetti", "Penne", "Ravioli", "Tortellini"), 0, "Gastronomie", Difficulty.EASY, explanation = "Les spaghetti sont les pâtes les plus consommées en Italie, représentant environ 25% du marché des pâtes sèches, grâce à leur polyvalence et leur association classique avec des sauces comme la carbonara ou la bolognaise."),
        Question(50754, "Quel est l'ingrédient principal de la vraie sauce bolognaise?", listOf("Tomate", "Viande", "Ail", "Oignon"), 1, "Gastronomie", Difficulty.HARD, explanation = "La sauce bolognaise traditionnelle, originaire de Bologne en Italie, est avant tout une préparation à base de viande hachée (souvent un mélange de bœuf et de porc), les tomates n'y étant qu'un élément secondaire."),
        Question(50755, "Quel est l'ingrédient principal du vrai pesto?", listOf("Tomate", "Basilic", "Ail", "Crème"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Le vrai pesto alla genovese est traditionnellement préparé avec du basilic frais, de l'ail, du parmesan, des pignons et de l'huile d'olive."),
        Question(50756, "Quel est le vin blanc français le plus prestigieux?", listOf("Sauternes", "Chablis", "Sauvignon Blanc", "Riesling"), 0, "Gastronomie", Difficulty.HARD, explanation = "Le Sauternes est un vin blanc liquoreux de Bordeaux, réputé pour sa complexité et sa capacité de vieillissement, produit à partir de raisins botrytisés."),
        Question(50757, "Quel est le vin rouge français le plus prestigieux?", listOf("Bordeaux", "Bourgogne", "Côtes du Rhône", "Châteauneuf-du-Pape"), 1, "Gastronomie", Difficulty.HARD, explanation = "La Bourgogne produit certains des vins rouges les plus réputés au monde, notamment à base de pinot noir, avec des appellations comme Romanée-Conti."),
        Question(50758, "Quel est le champagne le plus prestigieux?", listOf("Veuve Clicquot", "Krug", "Dom Pérignon", "Cristal"), 2, "Gastronomie", Difficulty.HARD, explanation = "Dom Pérignon est considéré comme le champagne le plus prestigieux car il est produit par Moët & Chandon et porte le nom du moine bénédictin qui a perfectionné la méthode de champagnisation au XVIIe siècle."),
        Question(50759, "Quel est l'aliment le plus cher du monde?", listOf("Safran", "Caviar", "Truffes", "Or alimentaire"), 2, "Gastronomie", Difficulty.HARD, explanation = "Les truffes, notamment la truffe blanche d'Alba, peuvent atteindre des prix exorbitants, jusqu'à plusieurs milliers d'euros le kilo, en raison de leur rareté et de leur cueillette difficile."),
        Question(50760, "Quel est le prix moyen d'un gramme de truffes blanches?", listOf("10 euros", "50 euros", "100 euros", "500 euros"), 1, "Gastronomie", Difficulty.HARD, explanation = "La truffe blanche d'Alba est un champignon très rare et difficile à cultiver, ce qui explique son prix élevé, atteignant souvent 50 euros le gramme sur les marchés."),
        Question(50761, "Quel est le plus grand restaurant du monde?", listOf("Thai Orchid", "Crystal Palace Buffet", "Bacchanal Buffet", "Hawker Chan"), 2, "Gastronomie", Difficulty.HARD, explanation = "Le Bacchanal Buffet à Las Vegas détient le record du plus grand restaurant du monde avec plus de 2 500 places assises."),
        Question(50762, "Quel est le plus petit restaurant du monde?", listOf("Chez Prune", "Tiny Thai", "Café Wisteria", "The Worlds Smallest Restaurant"), 3, "Gastronomie", Difficulty.HARD, explanation = "Situé à Bruxelles, ce restaurant ne peut accueillir qu’une seule table pour deux convives, ce qui lui vaut le titre de plus petit restaurant du monde."),
        Question(50763, "Quel est le plat qui a remporté le plus de prix gastronomiques?", listOf("Coq au vin", "Bouef à la Bourguignonne", "Paella", "Risotto"), 1, "Gastronomie", Difficulty.EXPERT, explanation = "Le bœuf bourguignon est un plat emblématique de la cuisine française, souvent primé pour sa richesse en saveurs et son héritage culinaire. Il a été consacré par de nombreux concours gastronomiques comme un classique indémodable."),
        Question(50764, "Quel est le type de cuisine qui est le plus courant dans le monde?", listOf("Chinoise", "Italienne", "Française", "Thaïlandaise"), 0, "Gastronomie", Difficulty.HARD, explanation = "La cuisine chinoise est la plus répandue dans le monde en raison de sa longue histoire, de sa diversité régionale et de sa diaspora importante."),
        Question(50765, "Quel est le légume le plus riche en calories?", listOf("Avocat", "Pomme de terre", "Olive", "Noix de coco"), 0, "Gastronomie", Difficulty.HARD, explanation = "L'avocat est un fruit-légume très riche en lipides, ce qui lui confère une densité calorique élevée, contrairement à la plupart des légumes qui sont pauvres en calories."),
        Question(50766, "Quel est le fruit le plus riche en vitamine C?", listOf("Orange", "Citron", "Kiwi", "Fraise"), 2, "Gastronomie", Difficulty.HARD, explanation = "Le kiwi contient environ 92 mg de vitamine C pour 100 g, dépassant ainsi l'orange qui en contient environ 53 mg."),
        Question(50767, "Quel est le nombre de calories dans une baguette française?", listOf("200", "400", "600", "800"), 2, "Gastronomie", Difficulty.HARD, explanation = "Une baguette française standard de 250 grammes contient environ 600 calories, principalement issues des glucides de la farine de blé."),
        Question(50768, "Quel est le nombre de variétés de vin français?", listOf("100", "500", "1000", "5000"), 2, "Gastronomie", Difficulty.EXPERT, explanation = "La France compte environ 1 000 variétés de vin, un chiffre qui reflète la diversité de ses cépages et de ses terroirs, bien que seules quelques dizaines soient largement cultivées."),
        Question(50769, "Quel est le pays le plus grand producteur de vin?", listOf("France", "Italie", "Espagne", "États-Unis"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "La France est historiquement le premier producteur mondial de vin, avec des régions comme Bordeaux, Bourgogne et Champagne. Elle rivalise avec l'Italie pour la première place selon les années."),
        Question(50770, "Quel est le pays le plus grand producteur de champagne?", listOf("France", "Italie", "Allemagne", "Espagne"), 0, "Gastronomie", Difficulty.EASY, explanation = "Le champagne est une appellation d'origine contrôlée protégée, exclusivement réservée aux vins produits dans la région de Champagne, en France."),
        Question(50771, "Quel est le pays le plus grand producteur de caviar?", listOf("France", "Russie", "Iran", "Kazakhstan"), 2, "Gastronomie", Difficulty.HARD, explanation = "L'Iran est le premier producteur mondial de caviar grâce à ses élevages d'esturgeons en mer Caspienne, qui fournissent le caviar de haute qualité le plus prisé."),
        Question(50772, "Quel est le pays le plus grand producteur de chocolat?", listOf("Belgique", "Suisse", "Côte d'Ivoire", "Ghana"), 2, "Gastronomie", Difficulty.HARD, explanation = "La Côte d'Ivoire est le premier producteur mondial de cacao, matière première du chocolat, assurant environ 40% de la production globale."),
        Question(50773, "Quel est le pays le plus grand producteur de café?", listOf("Colombie", "Brésil", "Éthiopie", "Vietnam"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Le Brésil domine la production mondiale de café depuis plus de 150 ans, grâce à son climat tropical et ses vastes terres agricoles. Il représente environ un tiers du café produit dans le monde."),
        Question(50774, "Quel est le pays le plus grand producteur de cacao?", listOf("Brésil", "Équateur", "Côte d'Ivoire", "Ghana"), 2, "Gastronomie", Difficulty.HARD, explanation = "La Côte d'Ivoire est le premier producteur mondial de cacao, représentant environ 40% de la production totale, grâce à ses conditions climatiques idéales et à une main-d'œuvre abondante."),
        Question(50775, "Quel est le nombre de plats traditionnels français?", listOf("50", "100", "200", "300"), 2, "Gastronomie", Difficulty.EXPERT, explanation = "L'inventaire du patrimoine culinaire français recense officiellement environ 200 plats traditionnels, reconnus pour leur authenticité et leur ancrage régional."),
        Question(50776, "Quel est le plat français le plus ancien connu?", listOf("Coq au vin", "Potage", "Rôti", "Fricassée"), 2, "Gastronomie", Difficulty.EXPERT, explanation = "Le rôti est considéré comme le plat français le plus ancien car il remonte à la préhistoire, où la cuisson de la viande à la broche au-dessus du feu était déjà pratiquée."),
        Question(50777, "Quel est le dessert français le plus ancien?", listOf("Tarte Tatin", "Crème brûlée", "Pâte de fruit", "Nougat"), 2, "Gastronomie", Difficulty.EXPERT, explanation = "La pâte de fruit est considérée comme le plus ancien dessert français, car elle était déjà préparée au Moyen Âge pour conserver les fruits, avant l’arrivée du sucre de canne."),
        Question(50778, "Quel est le type de cuisine qui est le plus sain?", listOf("Méditerranéenne", "Asiatique", "Française", "Américaine"), 0, "Gastronomie", Difficulty.HARD, explanation = "La cuisine méditerranéenne est riche en fruits, légumes, huile d'olive et poissons, ce qui réduit les risques de maladies cardiovasculaires."),
        Question(50779, "Quel est le nombre de calories dans une pizza moyenne?", listOf("600", "1000", "1500", "2000"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Une pizza moyenne de 30 cm contient environ 1000 calories, en moyenne, en raison de la pâte, du fromage et de la garniture."),
        Question(50780, "Quel est le nombre de calories dans une portion de frites?", listOf("200", "400", "600", "800"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Une portion standard de frites (environ 150 grammes) contient en moyenne 400 calories, en raison de la friture qui ajoute des lipides aux pommes de terre riches en amidon."),
        Question(50781, "Quel est le nombre de calories dans un hamburger moyen?", listOf("300", "500", "800", "1000"), 1, "Gastronomie", Difficulty.MEDIUM, explanation = "Un hamburger moyen (environ 150 à 200 grammes) contient généralement entre 450 et 550 calories, avec 500 comme valeur moyenne courante."),
        Question(50782, "Quel est le plat asiatique le plus populaire en occident?", listOf("Sushi", "Pad Thai", "Curry", "Riz frit"), 0, "Gastronomie", Difficulty.MEDIUM, explanation = "Le sushi, d'origine japonaise, s'est imposé en Occident grâce à sa présence massive dans les restaurants et supermarchés depuis les années 1980."),
        Question(50783, "Quel est le type de sushi le plus populaire?", listOf("California roll", "Dragon roll", "Philadelphia roll", "Spicy tuna"), 0, "Gastronomie", Difficulty.HARD, explanation = "Le California roll, créé aux États-Unis dans les années 1970, est le sushi le plus populaire car il utilise de l'avocat et du crabe, évitant le poisson cru pour plaire aux palais occidentaux."),
        Question(50784, "Quel est le type de curry le plus populaire en Inde?", listOf("Curry rouge", "Curry vert", "Curry jaune", "Tandoori"), 2, "Gastronomie", Difficulty.HARD, explanation = "Le curry jaune, souvent à base de curcuma, est le plus répandu en Inde, notamment dans les plats quotidiens comme le dal tadka."),
        Question(50785, "Quel est le nombre de types de pâtes en Italie?", listOf("100", "200", "300", "400"), 2, "Gastronomie", Difficulty.EXPERT, explanation = "L'Italie compte environ 300 types de pâtes différents, une diversité due aux variations régionales de formes, tailles et recettes traditionnelles.")
    )

    private fun philosophie(): List<Question> = listOf(
        // ===== PHILOSOPHIE (75 questions) =====
        Question(50786, "Quel philosophe grec a enseigné qu'il faut vivre selon la nature?", listOf("Platon", "Aristote", "Épicure", "Diogène"), 3, "Philosophie", Difficulty.MEDIUM, explanation = "Diogène, figure majeure du cynisme, prônait un retour à une vie simple et frugale, en accord avec les besoins naturels, rejetant les conventions sociales artificielles."),
        Question(50787, "Quel est le principe fondamental de la philosophie de Platon?", listOf("Le monde des idées", "La vertu est la connaissance", "La métaphysique de l'essence", "L'éthique de la vertu"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Platon distingue le monde sensible, imparfait et changeant, d'un monde intelligible et parfait, celui des Idées, qui sont les modèles éternels de toutes choses."),
        Question(50788, "Quel est le principe fondamental de la philosophie d'Aristote?", listOf("Le monde des idées", "La substance", "La métaphysique de l'essence", "La vertu est la connaissance"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Pour Aristote, la substance est le fondement de toute réalité, car elle représente ce qui existe par soi-même et supporte les propriétés accidentelles."),
        Question(50789, "Quel philosophe grec a fondé l'Académie?", listOf("Socrate", "Aristote", "Platon", "Pythagore"), 2, "Philosophie", Difficulty.EASY, explanation = "Platon a fondé l'Académie à Athènes vers 387 av. J.-C., une école philosophique majeure de l'Antiquité."),
        Question(50790, "Quel philosophe grec a fondé le Lycée?", listOf("Socrate", "Aristote", "Platon", "Pythagore"), 1, "Philosophie", Difficulty.EASY, explanation = "Aristote fonda le Lycée à Athènes en 335 av. J.-C., une école philosophique rivale de l'Académie de Platon."),
        Question(50791, "Quel est le principe fondamental de la philosophie de Socrate?", listOf("La vertu est la connaissance", "Le monde des idées", "L'essence et la substance", "La sagesse est ignorance"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Socrate affirmait que personne ne fait le mal volontairement, car agir mal résulte d'une ignorance du bien. Ainsi, acquérir la connaissance mène nécessairement à la vertu."),
        Question(50792, "Quel philosophe a énoncé le doute méthodique?", listOf("Descartes", "Spinoza", "Kant", "Leibniz"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Descartes a formulé le doute méthodique dans ses Méditations métaphysiques comme un outil pour parvenir à une certitude absolue, en remettant en cause toutes les connaissances jusqu'à trouver le cogito."),
        Question(50793, "Quel est le point de départ du cogito cartésien?", listOf("Je suis", "Je pense donc je suis", "Je doute donc je suis", "Je sens donc je suis"), 1, "Philosophie", Difficulty.EASY, explanation = "Le cogito cartésien part du doute méthodique : Descartes cherche une certitude indubitable et trouve que le fait même de douter prouve l'existence d'un sujet pensant."),
        Question(50794, "Quel philosophe a théorisé le contrat social?", listOf("Hobbes", "Rousseau", "Locke", "Montesquieu"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Dans son ouvrage Du contrat social (1762), Rousseau développe l'idée que la légitimité politique repose sur un accord volontaire entre les citoyens."),
        Question(50795, "Quel philosophe a énoncé que l'homme naît libre?", listOf("Hobbes", "Rousseau", "Locke", "Montesquieu"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Dans *Du contrat social* (1762), Rousseau affirme que l'homme naît libre mais que la société le corrompt, posant les bases de sa philosophie politique sur la souveraineté populaire."),
        Question(50796, "Quel est le concept central de la critique kantienne?", listOf("Les catégories de l'entendement", "Le phénomène et le noumène", "La raison pure", "L'impératif catégorique"), 1, "Philosophie", Difficulty.HARD, explanation = "Kant distingue le phénomène (ce qui apparaît à notre sensibilité) du noumène (la chose en soi, inaccessible à la connaissance). Cette distinction est centrale dans sa critique de la raison pure."),
        Question(50797, "Quel philosophe a développé la dialectique?", listOf("Hegel", "Marx", "Engels", "Feuerbach"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Hegel a formalisé la dialectique comme un processus triadique (thèse, antithèse, synthèse) pour expliquer le développement de l'Esprit et de l'histoire."),
        Question(50798, "Quel philosophe a énoncé le matérialisme dialectique?", listOf("Hegel", "Marx", "Engels", "Feuerbach"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Marx a développé le matérialisme dialectique avec Engels, en appliquant la dialectique hégélienne à une conception matérialiste de l'histoire et de la nature."),
        Question(50799, "Quel est le concept central du stoïcisme?", listOf("L'apatheia", "L'ataraxia", "La virtus", "La sabientia"), 0, "Philosophie", Difficulty.HARD, explanation = "L'apatheia désigne l'absence de passions irrationnelles, permettant au sage stoïcien de rester serein face aux événements extérieurs."),
        Question(50800, "Quel est le concept central de l'épicurisme?", listOf("Le plaisir", "L'ataraxia", "L'apatheia", "La virtus"), 0, "Philosophie", Difficulty.EASY, explanation = "Pour les épicuriens, le plaisir est le souverain bien, car il est le seul motif naturel de nos actions et le critère du bonheur, à condition d'être choisi avec raison pour éviter la douleur."),
        Question(50801, "Quel philosophe a énoncé le nihilisme?", listOf("Nietzsche", "Schopenhauer", "Heidegger", "Jaspers"), 0, "Philosophie", Difficulty.HARD, explanation = "Friedrich Nietzsche a popularisé le concept de nihilisme, notamment dans ses œuvres comme \"Ainsi parlait Zarathoustra\", où il annonce la \"mort de Dieu\" et la perte des valeurs absolues."),
        Question(50802, "Quel philosophe a développé l'existentialisme?", listOf("Sartre", "Heidegger", "Camus", "Merleau-Ponty"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Sartre a popularisé l'existentialisme dans son œuvre \"L'Être et le Néant\" (1943), affirmant que l'existence précède l'essence et que l'homme est libre de se définir par ses choix."),
        Question(50803, "Quel est le concept central du bouddhisme?", listOf("L'illumination", "Le nirvana", "Le karma", "La souffrance"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Le nirvana représente l'extinction de la souffrance et du cycle des renaissances dans le bouddhisme, atteint par l'élimination du désir et de l'ignorance."),
        Question(50804, "Quel est le concept central du confucianisme?", listOf("L'ordre social", "La vertu", "La piété filiale", "La bienveillance"), 2, "Philosophie", Difficulty.HARD, explanation = "La piété filiale, ou le respect des parents et des ancêtres, est le fondement de l'ordre social et moral dans la pensée de Confucius."),
        Question(50805, "Quel est le concept central du taoïsme?", listOf("Le Tao", "Le Chi", "Le Yin et le Yang", "La vertu"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Le Tao est le principe fondamental du taoïsme, représentant l'ordre naturel et la voie de l'univers, autour duquel s'articulent tous les enseignements de cette philosophie chinoise."),
        Question(50806, "Quel philosophe a énoncé que Dieu est mort?", listOf("Hegel", "Nietzsche", "Feuerbach", "Strauss"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Nietzsche a proclamé la mort de Dieu dans son ouvrage Le Gai Savoir (1882) pour critiquer le déclin de la foi religieuse dans la société moderne et annoncer l'avènement d'une nouvelle ère où l'homme doit créer ses propres valeurs."),
        Question(50807, "Quel est le concept central de la phénoménologie?", listOf("L'essence", "L'intentionnalité", "La substance", "Le phénomène"), 1, "Philosophie", Difficulty.HARD, explanation = "L'intentionnalité désigne la propriété de la conscience d'être toujours dirigée vers un objet, un concept fondamental pour Husserl et la phénoménologie."),
        Question(50808, "Quel philosophe a développé la phénoménologie?", listOf("Husserl", "Heidegger", "Merleau-Ponty", "Sartre"), 0, "Philosophie", Difficulty.HARD, explanation = "Edmund Husserl a fondé la phénoménologie au début du XXe siècle comme méthode d'analyse des structures de la conscience et des phénomènes tels qu'ils apparaissent."),
        Question(50809, "Quel est le concept central du pragmatisme?", listOf("L'utilité", "L'efficacité", "La conséquence", "La vérité"), 2, "Philosophie", Difficulty.HARD, explanation = "Le pragmatisme évalue la vérité d'une idée à l'aune de ses effets pratiques et de ses conséquences concrètes dans l'expérience."),
        Question(50810, "Quel philosophe a énoncé le principium identitatis indiscernibilium?", listOf("Descartes", "Leibniz", "Spinoza", "Newton"), 1, "Philosophie", Difficulty.EXPERT, explanation = "Leibniz a formulé ce principe d'identité des indiscernables, affirmant que deux entités distinctes ne peuvent avoir toutes leurs propriétés en commun."),
        Question(50811, "Quel est le concept central du rationalisme?", listOf("La raison", "L'expérience", "L'intuition", "La sensation"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Le rationalisme affirme que la raison est la source principale de la connaissance, s'opposant à l'empirisme qui privilégie l'expérience sensorielle."),
        Question(50812, "Quel est le concept central de l'empirisme?", listOf("La raison", "L'expérience", "L'intuition", "La sensation"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "L'empirisme affirme que toute connaissance humaine provient de l'expérience sensorielle, rejetant les idées innées."),
        Question(50813, "Quel philosophe a énoncé que la vérité est la correspondance?", listOf("Descartes", "Kant", "Frege", "Russell"), 2, "Philosophie", Difficulty.HARD, explanation = "Gottlob Frege a développé la théorie de la vérité comme correspondance dans le cadre de sa philosophie du langage et de la logique, où une proposition est vraie si elle correspond aux faits du monde."),
        Question(50814, "Quel philosophe a énoncé que la vérité est la cohérence?", listOf("Descartes", "Hegel", "Russell", "Frege"), 1, "Philosophie", Difficulty.HARD, explanation = "Pour Hegel, la vérité ne se trouve pas dans une correspondance simple entre l'idée et la réalité, mais dans la cohérence interne d'un système logique en développement dialectique."),
        Question(50815, "Quel philosophe a énoncé le principe de non-contradiction?", listOf("Héraclite", "Aristote", "Platon", "Socrate"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Aristote a formulé ce principe fondamental de la logique dans son ouvrage *Métaphysique*, affirmant qu'une chose ne peut pas être et ne pas être en même temps sous le même rapport."),
        Question(50816, "Quel est le concept central du déterminisme?", listOf("Le libre arbitre", "La causalité", "L'indéterminisme", "Le hasard"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Le déterminisme repose sur l'idée que tout événement, y compris les actions humaines, est causé par des facteurs antérieurs. La causalité en est donc le principe fondamental."),
        Question(50817, "Quel philosophe a énoncé la théorie de l'harmonie préétablie?", listOf("Descartes", "Spinoza", "Leibniz", "Newton"), 2, "Philosophie", Difficulty.HARD, explanation = "Leibniz a développé cette théorie pour expliquer l'interaction entre l'âme et le corps, selon laquelle Dieu a créé l'univers de sorte que tout se déroule en parallèle sans influence causale directe."),
        Question(50818, "Quel est le concept central du monisme?", listOf("L'existence d'une seule substance", "L'existence de deux substances", "L'existence de plusieurs substances", "L'absence de substance"), 0, "Philosophie", Difficulty.HARD, explanation = "Le monisme affirme que toute réalité se réduit à une seule substance ou principe fondamental, par opposition au dualisme qui en admet deux."),
        Question(50819, "Quel est le concept central du dualisme?", listOf("L'existence d'une seule substance", "L'existence de deux substances", "L'existence de plusieurs substances", "L'absence de substance"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Le dualisme, notamment chez Descartes, oppose la substance pensante (l'esprit) à la substance étendue (le corps), affirmant leur indépendance radicale."),
        Question(50820, "Quel est le concept central du matérialisme?", listOf("La matière est la réalité fondamentale", "L'esprit est la réalité fondamentale", "Les deux coexistent", "Aucune réalité fondamentale"), 0, "Philosophie", Difficulty.MEDIUM, explanation = "Le matérialisme affirme que toute réalité, y compris la conscience, découle de la matière. Cette position s'oppose à l'idéalisme, qui place l'esprit ou les idées à l'origine de tout."),
        Question(50821, "Quel est le concept central de l'idéalisme?", listOf("La matière est la réalité fondamentale", "L'esprit est la réalité fondamentale", "Les deux coexistent", "Aucune réalité fondamentale"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "L'idéalisme philosophique affirme que la réalité est fondamentalement mentale ou spirituelle, et que le monde matériel dépend de l'esprit pour exister."),
        Question(50822, "Quel philosophe a énoncé le principe du rasoir d'Occam?", listOf("William d'Occam", "Thomas d'Aquin", "Bonaventure", "Duns Scot"), 0, "Philosophie", Difficulty.HARD, explanation = "William d'Occam, moine franciscain du XIVe siècle, a formulé ce principe de parcimonie dans ses écrits logiques, souvent résumé par \"Les entités ne doivent pas être multipliées sans nécessité\"."),
        Question(50823, "Quel est le concept central du relativisme?", listOf("L'absolu n'existe pas", "Tout est relatif", "Aucune vérité objective", "Les trois sont équivalents"), 2, "Philosophie", Difficulty.HARD, explanation = "Le relativisme affirme que les vérités et les valeurs dépendent du contexte culturel, historique ou individuel, rejetant ainsi l'existence de vérités universelles et objectives."),
        Question(50824, "Quel philosophe a énoncé l'immoralisme?", listOf("Nietzsche", "Schopenhauer", "Hegel", "Kierkegaard"), 0, "Philosophie", Difficulty.HARD, explanation = "Nietzsche a développé l'immoralisme dans ses œuvres, notamment dans \"Par-delà le bien et le mal\", en critiquant la morale traditionnelle et en prônant une réévaluation des valeurs."),
        Question(50825, "Quel est le concept central de la théologie rationnelle?", listOf("La foi est la seule source de connaissance", "La raison peut connaître Dieu", "La révélation est supérieure à la raison", "Dieu ne peut pas être connu"), 1, "Philosophie", Difficulty.HARD, explanation = "La théologie rationnelle, ou théologie naturelle, soutient que des preuves de l'existence de Dieu peuvent être établies par le seul usage de la raison humaine, sans recours à la révélation divine."),
        Question(50826, "Quel est le concept central de l'apologétique?", listOf("La défense de la foi par la raison", "La critique de la religion", "La séparation de la foi et de la raison", "L'absence de Dieu"), 0, "Philosophie", Difficulty.HARD, explanation = "L'apologétique chrétienne, notamment chez des penseurs comme Tertullien ou Augustin, vise à justifier rationnellement les croyances religieuses face aux critiques."),
        Question(50827, "Quel philosophe a énoncé le problème du mal?", listOf("Augustine", "Thomas d'Aquin", "Leibniz", "Hume"), 3, "Philosophie", Difficulty.HARD, explanation = "David Hume a formulé le problème du mal dans ses Dialogues sur la religion naturelle, en opposant la puissance et la bonté divine à l'existence du mal dans le monde."),
        Question(50828, "Quel est le concept central de l'ontologie?", listOf("L'étude de ce qui est", "L'étude de la connaissance", "L'étude de la morale", "L'étude de la beauté"), 0, "Philosophie", Difficulty.HARD, explanation = "L'ontologie est la branche de la philosophie qui s'interroge sur la nature de l'être et de la réalité, d'où son objet central : l'étude de ce qui est."),
        Question(50829, "Quel est le concept central de l'épistémologie?", listOf("L'étude de ce qui est", "L'étude de la connaissance", "L'étude de la morale", "L'étude de la beauté"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "L'épistémologie est la branche de la philosophie qui examine la nature, l'origine et les limites de la connaissance humaine."),
        Question(50830, "Quel est le concept central de l'éthique?", listOf("L'étude de ce qui est", "L'étude de la connaissance", "L'étude de la morale", "L'étude de la beauté"), 2, "Philosophie", Difficulty.EASY, explanation = "L'éthique est la branche de la philosophie qui examine les principes du bien et du mal, et son concept central est l'étude systématique de la morale, c'est-à-dire des valeurs et des règles guidant les actions humaines."),
        Question(50831, "Quel est le concept central de l'esthétique?", listOf("L'étude de ce qui est", "L'étude de la connaissance", "L'étude de la morale", "L'étude de la beauté"), 3, "Philosophie", Difficulty.EASY, explanation = "L'esthétique est la branche de la philosophie qui étudie la nature de la beauté, de l'art et du goût. Son concept central est donc l'analyse de ce qui rend quelque chose beau ou laid."),
        Question(50832, "Quel philosophe a énoncé la théorie de l'amour courtois?", listOf("Dante", "Pétrarque", "Boccaccio", "Cavalcanti"), 3, "Philosophie", Difficulty.EXPERT, explanation = "Guido Cavalcanti, poète et philosophe italien du XIIIe siècle, a développé cette théorie dans son traité \"De l'amour\", influençant le courant du Dolce Stil Novo."),
        Question(50833, "Quel philosophe a énoncé le concept du surhomme?", listOf("Hegel", "Nietzsche", "Schopenhauer", "Kierkegaard"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Nietzsche a développé le concept du surhomme dans son œuvre \"Ainsi parlait Zarathoustra\", représentant un idéal d'humanité dépassant les valeurs morales traditionnelles."),
        Question(50834, "Quel est le concept central du taoïsme politique?", listOf("L'ordre social basé sur la raison", "L'ordre social basé sur le Tao", "L'absence d'ordre social", "Le chaos primordial"), 1, "Philosophie", Difficulty.HARD, explanation = "Le taoïsme politique prône un ordre social harmonieux et non-interventionniste, où le dirigeant suit le Tao (la Voie) pour gouverner avec simplicité et laisser-faire."),
        Question(50835, "Quel est le concept central du confucianisme politique?", listOf("L'ordre social basé sur la vertu", "L'ordre social basé sur la loi", "L'absence d'ordre social", "Le chaos primordial"), 0, "Philosophie", Difficulty.HARD, explanation = "Le confucianisme politique prône un ordre social fondé sur la vertu, où le souverain gouverne par l'exemple moral et la bienveillance, plutôt que par la loi ou la force."),
        Question(50836, "Quel est le concept central du légalisme chinois?", listOf("L'ordre social basé sur la vertu", "L'ordre social basé sur la loi", "L'absence d'ordre social", "Le chaos primordial"), 1, "Philosophie", Difficulty.HARD, explanation = "Le légalisme, développé par des penseurs comme Han Fei, prône un ordre social strict fondé sur des lois écrites et des récompenses/punitions, rejetant la morale confucéenne."),
        Question(50837, "Quel philosophe a énoncé que la justice est l'ordre social naturel?", listOf("Platon", "Aristote", "Cicéron", "Sénèque"), 2, "Philosophie", Difficulty.HARD, explanation = "Cicéron, dans son traité De la République, définit la justice comme l'ordre naturel qui harmonise la société, s'inspirant de la pensée stoïcienne sur la loi naturelle."),
        Question(50838, "Quel est le concept central du cosmopolitisme?", listOf("L'amour de son pays", "L'amour du monde", "L'absence de frontières morales", "La fraternité universelle"), 3, "Philosophie", Difficulty.HARD, explanation = "Le cosmopolitisme affirme que tous les êtres humains appartiennent à une même communauté mondiale, dépassant les frontières nationales. La fraternité universelle en est le principe fondamental."),
        Question(50839, "Quel philosophe a énoncé que la raison pratique est plus importante que la raison théorique?", listOf("Kant", "Hegel", "Schopenhauer", "Kierkegaard"), 0, "Philosophie", Difficulty.HARD, explanation = "Dans sa philosophie morale, Kant distingue la raison pratique, qui guide l'action selon la loi morale, de la raison théorique, qui se limite à la connaissance des phénomènes, accordant la primauté à la première."),
        Question(50840, "Quel est le concept central du voluntarisme?", listOf("La volonté est la réalité fondamentale", "L'intellect est la réalité fondamentale", "L'intuition est la réalité fondamentale", "L'imagination est la réalité fondamentale"), 0, "Philosophie", Difficulty.HARD, explanation = "Le volontarisme, notamment chez Schopenhauer et Nietzsche, affirme que la volonté, et non la raison, constitue le principe premier et essentiel de la réalité."),
        Question(50841, "Quel philosophe a énoncé que la volonté est aveugle?", listOf("Nietzsche", "Schopenhauer", "Hegel", "Kierkegaard"), 1, "Philosophie", Difficulty.HARD, explanation = "Pour Schopenhauer, la volonté est une force irrationnelle et aveugle qui pousse à l'action sans but conscient, contrairement à l'intellect qui n'en est qu'un instrument."),
        Question(50842, "Quel est le concept central de l'intuitionnisme?", listOf("La raison est la source de la connaissance", "L'intuition est la source de la connaissance", "L'expérience est la source de la connaissance", "La révélation est la source de la connaissance"), 1, "Philosophie", Difficulty.HARD, explanation = "L'intuitionnisme, en philosophie, affirme que certaines vérités fondamentales sont connues directement par intuition, sans recours à la raison ou aux sens. Cette position s'oppose au rationalisme et à l'empirisme en faisant de l'intuition la source première de la connaissance."),
        Question(50843, "Quel est le concept central du bergsonisme?", listOf("La durée est la réalité fondamentale", "L'espace est la réalité fondamentale", "Le temps est une illusion", "La matière est la réalité fondamentale"), 0, "Philosophie", Difficulty.EXPERT, explanation = "Pour Bergson, la durée est le temps vécu par la conscience, une continuité indivisible et créatrice, s'opposant au temps spatialisé et mesuré de la science."),
        Question(50844, "Quel est le concept central du platonisme mathématique?", listOf("Les nombres existent indépendamment", "Les nombres sont des constructions mentales", "Les nombres sont des conventions sociales", "Les nombres n'existent pas"), 0, "Philosophie", Difficulty.EXPERT, explanation = "Le platonisme mathématique affirme que les entités mathématiques, comme les nombres, sont des objets abstraits réels et éternels, existant indépendamment de l'esprit humain."),
        Question(50845, "Quel est le concept central du constructivisme?", listOf("Les objets mathématiques existent indépendamment", "Les objets mathématiques sont construits par l'esprit", "Les objets mathématiques sont des conventions sociales", "Les objets mathématiques n'existent pas"), 1, "Philosophie", Difficulty.EXPERT, explanation = "Le constructivisme, en philosophie des mathématiques, soutient que les objets mathématiques n'existent pas indépendamment de l'esprit humain mais sont créés par l'activité mentale."),
        Question(50846, "Quel philosophe a énoncé la morale des intentions?", listOf("Kant", "Bentham", "Mill", "Moore"), 0, "Philosophie", Difficulty.HARD, explanation = "Kant a développé le concept de « bonne volonté » dans sa philosophie morale, affirmant que seule l'intention guidée par le devoir moral donne sa valeur à une action, indépendamment de ses conséquences."),
        Question(50847, "Quel philosophe a énoncé l'utilitarisme?", listOf("Kant", "Bentham", "Mill", "Moore"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Jeremy Bentham a fondé l'utilitarisme classique au XVIIIe siècle, théorisant que la morale doit maximiser le bonheur pour le plus grand nombre."),
        Question(50848, "Quel est le concept central de la vertu éthique?", listOf("L'habitude de bien agir", "La raison pure", "L'intention pure", "L'action conforme à la loi"), 0, "Philosophie", Difficulty.HARD, explanation = "Pour Aristote, la vertu éthique n'est pas innée mais s'acquiert par la pratique répétée de bonnes actions, devenant ainsi une disposition stable ou habitude."),
        Question(50849, "Quel philosophe a énoncé que la vertu est une habitude?", listOf("Platon", "Aristote", "Socrate", "Cicéron"), 1, "Philosophie", Difficulty.MEDIUM, explanation = "Dans l'Éthique à Nicomaque, Aristote définit la vertu comme une disposition acquise par la répétition d'actions, donc une habitude."),
        Question(50850, "Quel est le concept central du scepticisme antique?", listOf("Aucune connaissance n'est possible", "La connaissance est relative", "La connaissance est impossible à justifier", "Le doute est le point de départ"), 2, "Philosophie", Difficulty.HARD, explanation = "Le scepticisme antique, représenté par Pyrrhon et Sextus Empiricus, affirme que toute croyance manque de fondement certain, rendant la connaissance impossible à justifier.")
    )

    private fun art(): List<Question> = listOf(
        // ===== ART (75 questions) =====
        Question(50851, "Quel est le mouvement artistique le plus ancien?", listOf("Préhistorique", "Classique", "Renaissance", "Baroque"), 0, "Art", Difficulty.EASY, explanation = "L'art préhistorique, avec ses peintures rupestres et ses sculptures, remonte à des dizaines de milliers d'années, bien avant l'émergence des civilisations antiques."),
        Question(50852, "Quel est l'art de la préhistoire le plus connu?", listOf("Sculpture", "Peinture rupestre", "Poterie", "Bijoux"), 1, "Art", Difficulty.EASY, explanation = "Les peintures rupestres, comme celles de la grotte de Lascaux, sont les témoignages artistiques les plus célèbres de la Préhistoire, datant du Paléolithique supérieur."),
        Question(50853, "Quel est le plus ancien art plastique connu?", listOf("Peinture", "Sculpture", "Architecture", "Céramique"), 0, "Art", Difficulty.EASY, explanation = "Les peintures rupestres découvertes dans des grottes comme celles de Chauvet ou d'El Castillo datent de plus de 30 000 ans, ce qui en fait les plus anciennes formes d'art plastique connues."),
        Question(50854, "Quel est le mouvement artistique de la Renaissance?", listOf("L'art antique revit", "L'humanisme et l'individualité", "Le réalisme", "L'abstraction"), 1, "Art", Difficulty.MEDIUM, explanation = "La Renaissance met l'accent sur l'humanisme, qui place l'homme au centre des préoccupations, et sur l'individualité, valorisant la singularité de chaque artiste et sujet."),
        Question(50855, "Quel est le mouvement artistique du Baroque?", listOf("La simplicité", "L'émotions intense et le dramatisme", "La raison", "L'abstraction"), 1, "Art", Difficulty.MEDIUM, explanation = "Le baroque, né au XVIIe siècle, se caractérise par l'exubérance, le mouvement et un fort contraste entre ombre et lumière pour susciter des émotions intenses et un sens du dramatisme."),
        Question(50856, "Quel est le mouvement artistique du Classicisme?", listOf("L'émotion intense", "L'ordre et la raison", "L'abstraction", "L'expression de l'inconscient"), 1, "Art", Difficulty.MEDIUM, explanation = "Le Classicisme, né au XVIIe siècle, privilégie l'ordre, la raison et l'équilibre, en s'inspirant de l'art antique."),
        Question(50857, "Quel est le mouvement artistique du Romantisme?", listOf("L'ordre et la raison", "L'émotion, la passion et l'individualité", "L'abstraction", "La réalité objective"), 1, "Art", Difficulty.EASY, explanation = "Le Romantisme a émergé en réaction au classicisme et au rationalisme des Lumières, mettant l'accent sur l'expression des sentiments, la subjectivité et la puissance de l'imagination individuelle."),
        Question(50858, "Quel est le mouvement artistique du Réalisme?", listOf("L'ordre et la raison", "L'émotion et la passion", "La représentation de la réalité", "L'abstraction"), 2, "Art", Difficulty.MEDIUM, explanation = "Le Réalisme, né au XIXe siècle, privilégie la représentation fidèle de la vie quotidienne et des classes populaires, en réaction au romantisme et à ses idéalisations."),
        Question(50859, "Quel est le mouvement artistique de l'Impressionnisme?", listOf("La précision des détails", "L'impression visuelle et la lumière", "L'abstraction", "L'expression de l'inconscient"), 1, "Art", Difficulty.EASY, explanation = "L'impressionnisme se concentre sur la capture des impressions visuelles fugitives et des effets de lumière, plutôt que sur les détails précis ou les sujets académiques."),
        Question(50860, "Quel est le mouvement artistique du Symbolisme?", listOf("La réalité objective", "Les symboles et l'inconscient", "L'abstraction", "L'expression de l'ordre"), 1, "Art", Difficulty.MEDIUM, explanation = "Le Symbolisme, né à la fin du XIXe siècle, privilégiait l'expression des idées, des émotions et des mystères de l'inconscient à travers des symboles plutôt que la représentation réaliste."),
        Question(50861, "Quel est le mouvement artistique du Cubisme?", listOf("La perspective simple", "La déconstruction des formes", "L'abstraction", "Le réalisme"), 1, "Art", Difficulty.MEDIUM, explanation = "Le cubisme, initié par Picasso et Braque vers 1907, se caractérise par la fragmentation des objets en formes géométriques et leur représentation sous plusieurs angles simultanés."),
        Question(50862, "Quel est le mouvement artistique du Surréalisme?", listOf("La réalité objective", "Les symboles et l'inconscient", "L'abstraction", "L'expression du rêve"), 3, "Art", Difficulty.MEDIUM, explanation = "Le surréalisme, fondé par André Breton, cherche à libérer la pensée en explorant l'inconscient et le rêve, considéré comme une source d'inspiration pure."),
        Question(50863, "Quel est le mouvement artistique de l'Expressionnisme?", listOf("La réalité objective", "L'émotion intense et la subjectivité", "L'abstraction", "L'ordre et la raison"), 1, "Art", Difficulty.MEDIUM, explanation = "L'Expressionnisme, né au début du XXe siècle, privilégie la représentation des émotions subjectives et des sentiments intenses plutôt que la réalité objective."),
        Question(50864, "Quel est le mouvement artistique du Fauvisme?", listOf("La précision des couleurs", "La couleur intense et libre", "L'abstraction", "L'ordre et la raison"), 1, "Art", Difficulty.MEDIUM, explanation = "Le Fauvisme, apparu au début du XXe siècle, se caractérise par l'utilisation de couleurs vives et non naturalistes, appliquées de manière expressive et spontanée, sans souci de réalisme."),
        Question(50865, "Quel est le mouvement artistique de l'Abstraction?", listOf("La représentation réaliste", "La non-représentation", "L'expression du rêve", "L'ordre et la raison"), 1, "Art", Difficulty.EASY, explanation = "L'abstraction se définit par le refus de représenter le monde visible. Elle privilégie les formes, les couleurs et les lignes pour elles-mêmes, sans référence à un sujet reconnaissable."),
        Question(50866, "Quel est le mouvement artistique du Dadaïsme?", listOf("L'ordre et la raison", "L'absurdité et le non-sens", "L'expression du rêve", "La réalité objective"), 1, "Art", Difficulty.HARD, explanation = "Le Dadaïsme, né pendant la Première Guerre mondiale, rejetait la logique et la raison en prônant l'absurdité et le non-sens comme réaction contre les valeurs ayant mené au conflit."),
        Question(50867, "Quel est le mouvement artistique du Futurisme?", listOf("Le passé", "L'avenir et la technologie", "L'expression du rêve", "La réalité objective"), 1, "Art", Difficulty.MEDIUM, explanation = "Le Futurisme, né en Italie au début du XXe siècle, exaltait la vitesse, la technologie et le dynamisme de la vie moderne, rejetant le passé pour célébrer l'avenir."),
        Question(50868, "Quel artiste est le plus célèbre de la Renaissance?", listOf("Michel-Ange", "Léonard de Vinci", "Botticelli", "Raphaël"), 1, "Art", Difficulty.EASY, explanation = "Léonard de Vinci est considéré comme l'archétype de l'homme de la Renaissance pour ses talents multiples en peinture, sculpture, architecture et sciences, avec des chefs-d'œuvre comme La Joconde et La Cène."),
        Question(50869, "Quel artiste est le plus célèbre du Baroque?", listOf("Caravaggio", "Rembrandt", "Velázquez", "Rubens"), 0, "Art", Difficulty.MEDIUM, explanation = "Caravaggio est considéré comme le maître du Baroque pour son usage révolutionnaire du clair-obscur et son réalisme dramatique, qui ont profondément influencé la peinture européenne du XVIIe siècle."),
        Question(50870, "Quel artiste est le plus célèbre du Classicisme?", listOf("Ingres", "David", "Poussin", "Lorrain"), 1, "Art", Difficulty.MEDIUM, explanation = "Jacques-Louis David est considéré comme le chef de file du Classicisme français, notamment pour ses tableaux comme Le Serment des Horaces. Il incarne l'esthétique néoclassique de la fin du XVIIIe siècle."),
        Question(50871, "Quel artiste est le plus célèbre du Romantisme?", listOf("Delacroix", "Géricault", "Constable", "Turner"), 0, "Art", Difficulty.MEDIUM, explanation = "Eugène Delacroix est considéré comme le chef de file du Romantisme en peinture française, notamment pour des œuvres comme La Liberté guidant le peuple."),
        Question(50872, "Quel artiste est le plus célèbre du Réalisme?", listOf("Courbet", "Corot", "Millet", "Daumier"), 0, "Art", Difficulty.MEDIUM, explanation = "Gustave Courbet est considéré comme le chef de file du mouvement réaliste au XIXe siècle, s'opposant au romantisme en peignant des scènes de la vie quotidienne et des travailleurs."),
        Question(50873, "Quel artiste est le plus célèbre de l'Impressionnisme?", listOf("Monet", "Renoir", "Degas", "Sisley"), 0, "Art", Difficulty.EASY, explanation = "Claude Monet est considéré comme le chef de file de l'impressionnisme, notamment grâce à son tableau \"Impression, soleil levant\" qui a donné son nom au mouvement."),
        Question(50874, "Quel artiste est le plus célèbre du Symbolisme?", listOf("Klimt", "Mucha", "Moreau", "Beardsley"), 1, "Art", Difficulty.HARD, explanation = "Alphonse Mucha est un peintre et affichiste tchèque, figure majeure du Symbolisme et de l'Art nouveau, célèbre pour ses œuvres décoratives et ses représentations de femmes élégantes."),
        Question(50875, "Quel artiste est le plus célèbre du Cubisme?", listOf("Braque", "Picasso", "Gris", "Léger"), 1, "Art", Difficulty.MEDIUM, explanation = "Picasso, avec Georges Braque, a fondé le mouvement cubiste au début du XXe siècle, révolutionnant la représentation de l'espace et des formes en peinture."),
        Question(50876, "Quel artiste est le plus célèbre du Surréalisme?", listOf("Dalí", "Miró", "Magritte", "Ernst"), 0, "Art", Difficulty.MEDIUM, explanation = "Salvador Dalí est l'artiste le plus emblématique du surréalisme grâce à ses œuvres oniriques et provocatrices comme \"La Persistance de la mémoire\"."),
        Question(50877, "Quel artiste est le plus célèbre de l'Expressionnisme?", listOf("Munch", "Kirchner", "Nolde", "Schiele"), 0, "Art", Difficulty.MEDIUM, explanation = "Edvard Munch, peintre norvégien, est considéré comme le précurseur et figure majeure de l'expressionnisme, notamment avec son œuvre emblématique \"Le Cri\"."),
        Question(50878, "Quel artiste est le plus célèbre du Fauvisme?", listOf("Matisse", "Derain", "Vlaminck", "Dufy"), 0, "Art", Difficulty.MEDIUM, explanation = "Henri Matisse est considéré comme le chef de file du Fauvisme, mouvement marqué par l'usage de couleurs vives et pures, notamment dans ses œuvres comme \"La Danse\"."),
        Question(50879, "Quel artiste est le plus célèbre de l'Abstraction?", listOf("Kandinsky", "Mondrian", "Malevitch", "Pollock"), 3, "Art", Difficulty.MEDIUM, explanation = "Jackson Pollock est reconnu comme le chef de file de l'expressionnisme abstrait américain, notamment pour sa technique de dripping qui a révolutionné l'art abstrait dans les années 1940-1950."),
        Question(50880, "Quel est le plus célèbre tableau de Léonard de Vinci?", listOf("La Cène", "La Joconde", "La Vierge aux Rochers", "La Vitruve"), 1, "Art", Difficulty.EASY, explanation = "Peint entre 1503 et 1519, ce portrait de Mona Lisa est exposé au musée du Louvre à Paris et est mondialement reconnu pour son sourire énigmatique et son sfumato."),
        Question(50881, "Quel est le plus célèbre tableau de Michel-Ange?", listOf("La Création d'Adam", "La Dernière Cène", "La Nuit étoilée", "Les Noces de Cana"), 0, "Art", Difficulty.EASY, explanation = "Peinte sur le plafond de la chapelle Sixtine au Vatican entre 1508 et 1512, cette fresque représente le moment où Dieu donne la vie à Adam."),
        Question(50882, "Quel est le plus célèbre tableau de Raphaël?", listOf("La Transfiguration", "La Madone Sixtine", "La Madone à la Chaise", "La Madone du Châtiment"), 0, "Art", Difficulty.HARD, explanation = "La Transfiguration est considérée comme le chef-d'œuvre ultime de Raphaël, peint en 1520, année de sa mort. Cette œuvre monumentale, exposée aux Musées du Vatican, illustre l'épisode biblique de la transfiguration du Christ."),
        Question(50883, "Quel est le plus célèbre tableau de Caravaggio?", listOf("La Vocation de Saint Matthieu", "L'Appel de Saint Matthieu", "La Mort de la Vierge", "Judith Décapitant Holopherne"), 1, "Art", Difficulty.HARD, explanation = "L'Appel de saint Matthieu, peint vers 1600, est l'une des œuvres les plus emblématiques du Caravage, marquant le début du baroque avec son usage dramatique du clair-obscur."),
        Question(50884, "Quel est le plus célèbre tableau de Rembrandt?", listOf("La Ronde de Nuit", "L'Archange Raphaël", "Le Retour du Fils Prodigue", "Autoportrait"), 0, "Art", Difficulty.MEDIUM, explanation = "Peint en 1642, La Ronde de Nuit est le chef-d'œuvre le plus connu de Rembrandt, célèbre pour son jeu de clair-obscur et sa composition dynamique représentant une milice civique."),
        Question(50885, "Quel est le plus célèbre tableau de Velázquez?", listOf("Las Meninas", "Le Christ à la Croix", "La Reddition de Breda", "Vieille Femme Cuisinant des Œufs"), 0, "Art", Difficulty.HARD, explanation = "Las Meninas est considéré comme le chef-d'œuvre de Diego Velázquez, peint en 1656, et fascine par sa composition complexe et son jeu de regards entre le peintre, le modèle et le spectateur."),
        Question(50886, "Quel est le plus célèbre tableau de Delacroix?", listOf("La Liberté Guidant le Peuple", "L'Entrée de Croisés", "La Mort de Sardanapale", "Scène de Massacre de Scio"), 0, "Art", Difficulty.MEDIUM, explanation = "Peint en 1830, ce tableau commémore les Trois Glorieuses, les journées révolutionnaires qui renversèrent Charles X. Il est devenu un symbole universel de la liberté et de la République française."),
        Question(50887, "Quel est le plus célèbre tableau de Courbet?", listOf("Un Enterrement à Ornans", "L'Origine du Monde", "Les Demoiselles de Village", "Les Baigneuses"), 0, "Art", Difficulty.HARD, explanation = "Un Enterrement à Ornans est le tableau le plus célèbre de Gustave Courbet car il a marqué une rupture avec le romantisme en représentant une scène de la vie rurale ordinaire avec un réalisme cru et monumental."),
        Question(50888, "Quel est le plus célèbre tableau de Monet?", listOf("Les Nymphéas", "Impression Soleil Levant", "La Gare Saint-Lazare", "Rouen Cathedral"), 1, "Art", Difficulty.EASY, explanation = "Impression, soleil levant est le tableau qui a donné son nom au mouvement impressionniste, présenté en 1874 lors de la première exposition du groupe."),
        Question(50889, "Quel est le plus célèbre tableau de Van Gogh?", listOf("La Nuit Étoilée", "Tournesols", "La Chambre", "L'Église d'Auvers"), 0, "Art", Difficulty.EASY, explanation = "Peinte en 1889 lors de son séjour à l'asile de Saint-Rémy-de-Provence, cette œuvre est devenue iconique pour son ciel tourbillonnant et son usage expressif de la couleur."),
        Question(50890, "Quel est le plus célèbre tableau de Picasso?", listOf("Les Demoiselles d'Avignon", "Guernica", "La Persistance de la Mémoire", "Le Cri"), 1, "Art", Difficulty.EASY, explanation = "Guernica, peint en 1937, dénonce le bombardement de la ville basque du même nom pendant la guerre d'Espagne. Cette œuvre monumentale est devenue un symbole universel de l'horreur de la guerre."),
        Question(50891, "Quel est le plus célèbre tableau de Dalí?", listOf("Les Demoiselles d'Avignon", "La Persistance de la Mémoire", "Guernica", "Le Cri"), 1, "Art", Difficulty.MEDIUM, explanation = "Peint en 1931, ce tableau est mondialement connu pour ses montres molles qui symbolisent la relativité du temps et la théorie de la relativité d'Einstein."),
        Question(50892, "Quel est le plus célèbre tableau de Matisse?", listOf("La Danse", "La Joie de Vivre", "Les Demoiselles d'Avignon", "Guernica"), 0, "Art", Difficulty.HARD, explanation = "La Danse est une œuvre majeure de Matisse, commandée en 1909 pour le collectionneur russe Chtchoukine, et elle incarne son style fauve par ses couleurs vives et ses formes simplifiées."),
        Question(50893, "Quel est le plus célèbre tableau de Munch?", listOf("Le Cri", "La Fille Malade", "Le Baiser", "Angoisse"), 0, "Art", Difficulty.MEDIUM, explanation = "Le Cri, peint en 1893, est l'œuvre la plus emblématique d'Edvard Munch, symbolisant l'angoisse existentielle et devenant une icône de l'art moderne."),
        Question(50894, "Quel est le plus célèbre tableau de Klimt?", listOf("Le Baiser", "Portrait d'Adèle Bloch-Bauer", "Les Trois Âges", "Danaé"), 0, "Art", Difficulty.MEDIUM, explanation = "Le Baiser, peint entre 1907 et 1908, est l'œuvre la plus emblématique de Gustav Klimt, représentant un couple enlacé dans des ornements dorés typiques de sa période dorée."),
        Question(50895, "Quel est le plus célèbre tableau de Pollock?", listOf("Abstraction Number 1", "No. 5, 1948", "Convergence", "Number 8"), 1, "Art", Difficulty.HARD, explanation = "Le tableau No. 5, 1948 est une œuvre emblématique du dripping de Jackson Pollock, vendue en 2006 pour 140 millions de dollars, ce qui en fait l'une des toiles les plus chères au monde."),
        Question(50896, "Quel est le plus célèbre tableau de Mondrian?", listOf("Composition II en Rouge Bleu et Jaune", "Composition avec Jaune et Bleu", "Broadway Boogie Woogie", "Composition 1921"), 2, "Art", Difficulty.HARD, explanation = "Broadway Boogie Woogie est l'œuvre la plus célèbre de Piet Mondrian, peinte en 1942-1943, car elle synthétise son style néoplastique avec une évocation dynamique de New York."),
        Question(50897, "Quel est le plus célèbre tableau de Kandinsky?", listOf("Impression III", "Composition VIII", "Yellow-Red-Blue", "Black Lines"), 1, "Art", Difficulty.HARD, explanation = "Composition VIII, peinte en 1923, est considérée comme une œuvre majeure de l'art abstrait, illustrant la théorie des formes et des couleurs développée par Kandinsky."),
        Question(50898, "Quel est le plus célèbre tableau de Malevitch?", listOf("Carré Noir sur Fond Blanc", "Composition Suprématiste", "Carré Rouge", "Blanc sur Blanc"), 3, "Art", Difficulty.HARD, explanation = "Malevitch, fondateur du suprématisme, a poussé l'abstraction à son extrême avec \"Blanc sur blanc\" (1918), un carré blanc sur fond blanc, symbole de la pureté absolue de l'art non figuratif."),
        Question(50899, "Quel est le plus célèbre tableau de Miró?", listOf("La Naissance du Monde", "Bleu II", "Le Carnaval d'Arlequin", "Nuit"), 0, "Art", Difficulty.HARD, explanation = "La Naissance du Monde est considérée comme l'œuvre la plus célèbre de Joan Miró, peinte en 1925, car elle marque un tournant vers son style surréaliste abstrait et onirique."),
        Question(50900, "Quel est le plus célèbre tableau de Magritte?", listOf("La Persistance de la Mémoire", "Le Fils de L'Homme", "La Trahison des Images", "Le Ciel et la Fenêtre"), 1, "Art", Difficulty.HARD, explanation = "Le Fils de l'Homme est l'autoportrait le plus connu de René Magritte, représentant un homme au chapeau melon dont le visage est caché par une pomme verte."),
        Question(50901, "Quel est le musée le plus célèbre du monde?", listOf("Louvre", "Vatican", "Uffizi", "MoMA"), 0, "Art", Difficulty.EASY, explanation = "Le Louvre à Paris est le musée le plus visité au monde, abritant des chefs-d'œuvre comme la Joconde et la Vénus de Milo."),
        Question(50902, "Quel est le plus ancien musée d'art du monde?", listOf("Musée Officiel de Florence", "Galerie des Offices", "Louvre", "Vatican"), 2, "Art", Difficulty.HARD, explanation = "Le Louvre, ouvert en 1793 à Paris, est considéré comme le premier musée public d'art au monde, établi à partir des collections royales françaises."),
        Question(50904, "Quel est le musée d'art moderne le plus célèbre du monde?", listOf("Louvre", "Vatican", "MoMA", "Guggenheim"), 2, "Art", Difficulty.MEDIUM, explanation = "Le Museum of Modern Art de New York, fondé en 1929, est considéré comme le musée d'art moderne le plus influent au monde, abritant des chefs-d'œuvre comme Les Demoiselles d'Avignon de Picasso."),
        Question(50905, "Quel est le plus ancien château-musée du monde?", listOf("Versailles", "Château du Louvre", "Palazzo Pitti", "Château de Fontainebleau"), 1, "Art", Difficulty.HARD, explanation = "Le château du Louvre, forteresse médiévale devenue résidence royale, a été transformé en musée en 1793, ce qui en fait le plus ancien musée public du monde."),
        Question(50906, "Quel est le plus grand château-musée du monde?", listOf("Versailles", "Château du Louvre", "Palazzo Pitti", "Hermitage"), 0, "Art", Difficulty.MEDIUM, explanation = "Le château de Versailles est le plus grand château-musée du monde, avec une superficie de 63 154 m² et plus de 60 000 œuvres d'art."),
        Question(50907, "Quel est le plus ancien art rupestre connu?", listOf("Grotte de Chauvet", "Grotte d'Altamira", "Grotte de Lascaux", "Grotte du Pech-Merle"), 0, "Art", Difficulty.HARD, explanation = "Datée d'environ 36 000 ans, la grotte Chauvet, en Ardèche, contient les plus anciennes peintures rupestres figuratives connues à ce jour."),
        Question(50908, "Quel est le plus ancien temple connu?", listOf("Temple de Jéricho", "Temple du Karnak", "Temple de Karnak", "Temple de Göbekli Tepe"), 3, "Art", Difficulty.HARD, explanation = "Le temple de Göbekli Tepe, situé dans l'actuelle Turquie, date d'environ 9600 avant notre ère, soit plus de 6000 ans avant Stonehenge. Il est considéré comme le plus ancien lieu de culte monumental découvert à ce jour."),
        Question(50909, "Quel est le plus ancien amphithéâtre connu?", listOf("Colosseum", "Théâtre de Demetrius", "Théâtre de Pompée", "Amphithéâtre d'Orange"), 1, "Art", Difficulty.HARD, explanation = "Le Théâtre de Demetrius, situé à Délos en Grèce, date du IVe siècle av. J.-C., ce qui en fait le plus ancien amphithéâtre connu."),
        Question(50910, "Quel est le plus haut obélisque du monde?", listOf("Obélisque de Louxor", "Obélisque de Washington", "Obélisque de New York", "Obélisque du Caire"), 0, "Art", Difficulty.HARD, explanation = "L'obélisque de Louxor, situé sur la place de la Concorde à Paris, mesure 23 mètres de haut et est le plus grand obélisque monolithe jamais transporté depuis l'Égypte antique."),
        Question(50911, "Quel est le plus grand palais du monde?", listOf("Palais de Versailles", "Palais du Kremlin", "Palais de Potala", "Palais d'Alhamabra"), 2, "Art", Difficulty.HARD, explanation = "Le Palais de Potala, situé à Lhassa au Tibet, est considéré comme le plus grand palais du monde avec ses 400 000 mètres carrés."),
        Question(50912, "Quel est le plus grand temple du monde?", listOf("Angkor Vat", "Temple de Karnak", "Temple du Taj Mahal", "Temple de Borobudur"), 0, "Art", Difficulty.HARD, explanation = "Angkor Vat, au Cambodge, est considéré comme le plus grand temple du monde en termes de superficie, s'étendant sur plus de 162 hectares."),
        Question(50913, "Quel est le plus grand fresco du monde?", listOf("Fresque Systine", "Fresque de la Création d'Adam", "Fresque de Michelangelo", "Fresque de Raphaël"), 2, "Art", Difficulty.EXPERT, explanation = "La fresque du plafond de la chapelle Sixtine, peinte par Michel-Ange entre 1508 et 1512, est considérée comme la plus grande fresque du monde, couvrant plus de 500 mètres carrés."),
        Question(50914, "Quel est le plus grand vitrail du monde?", listOf("Vitrail de Chartres", "Vitrail de Notre-Dame", "Vitrail de Cologne", "Vitrail de Rouen"), 2, "Art", Difficulty.EXPERT, explanation = "Le vitrail de la cathédrale de Cologne, en Allemagne, est considéré comme le plus grand du monde avec ses 1 200 mètres carrés de surface. Il a été installé en 2007 et conçu par l'artiste Gerhard Richter."),
        Question(50915, "Quel est le plus ancien type d'architecture connu?", listOf("L'architecture grecque", "L'architecture égyptienne", "L'architecture mégalithique", "L'architecture romaine"), 2, "Art", Difficulty.HARD, explanation = "L'architecture mégalithique, apparue au Néolithique, est la plus ancienne forme d'architecture connue, avec des structures comme les dolmens et menhirs datant de plusieurs millénaires avant notre ère."),
        Question(50916, "Quel est le plus ancien style architectural?", listOf("Corinthien", "Dorique", "Ionique", "Toscan"), 1, "Art", Difficulty.HARD, explanation = "Le style dorique est le plus ancien des trois ordres architecturaux grecs classiques, apparu vers le VIIe siècle avant J.-C. Il se caractérise par des colonnes robustes et sans base."),
        Question(50917, "Quel est le plus grand dôme du monde?", listOf("Dôme du Panthéon", "Dôme de la Cathédrale de Florence", "Dôme de Saint-Pierre", "Dôme du Taj Mahal"), 1, "Art", Difficulty.HARD, explanation = "Construit par Brunelleschi au XVe siècle, le dôme de la cathédrale de Florence est le plus grand dôme en maçonnerie jamais construit, avec un diamètre de 45,5 mètres."),
        Question(50918, "Quel est le plus grand arc du monde?", listOf("Arc de Triomphe", "Arc de Titus", "Pont de Brooklyn", "Pont du Golden Gate"), 2, "Art", Difficulty.HARD, explanation = "Le Pont de Brooklyn est souvent considéré comme le plus grand arc du monde en raison de sa portée de 486 mètres lors de son achèvement en 1883, un record pour l'époque."),
        Question(50919, "Quel est l'art le plus ancien de la civilisation?", listOf("Peinture", "Sculpture", "Danse", "Musique"), 3, "Art", Difficulty.EXPERT, explanation = "Des peintures rupestres vieilles de 40 000 ans montrent des figures dansant, suggérant que la musique existait avant l'art visuel. Les premiers instruments, comme des flûtes en os, datent d'au moins 35 000 ans."),
        Question(50920, "Quel est le prix le plus cher jamais payé pour une œuvre d'art?", listOf("Cent millions", "Trois cents millions", "Quatre cents millions", "Cinq cents millions"), 2, "Art", Difficulty.EXPERT, explanation = "Le tableau Salvator Mundi, attribué à Léonard de Vinci, a été vendu pour 450 millions de dollars en 2017, soit environ 400 millions d'euros."),
        Question(50921, "Quel est l'artiste le plus prolifique de tous les temps?", listOf("Picasso", "Matisse", "Michelangelo", "Leonardo da Vinci"), 0, "Art", Difficulty.HARD, explanation = "Picasso a produit plus de 50 000 œuvres, incluant peintures, dessins et sculptures, ce qui dépasse largement la production d'autres grands artistes comme Rembrandt ou Van Gogh."),
        Question(50922, "Quel est l'artiste qui a vendu le plus de copies de ses œuvres?", listOf("Van Gogh", "Picasso", "Warhol", "Leonardo da Vinci"), 2, "Art", Difficulty.HARD, explanation = "Andy Warhol a popularisé la sérigraphie, permettant de produire des multiples de ses œuvres comme les Campbell's Soup Cans, ce qui en fait l'artiste ayant vendu le plus de copies."),
        Question(50923, "Quel est le style de peinture le plus difficile?", listOf("Abstraction", "Réalisme", "Impressionnisme", "Surrealisme"), 1, "Art", Difficulty.EXPERT, explanation = "Le réalisme exige une maîtrise technique poussée pour reproduire fidèlement les détails, les proportions et les jeux de lumière, ce qui le rend particulièrement exigeant pour les artistes."),
        Question(50924, "Quel est l'art qui nécessite le plus de temps de réalisation?", listOf("Fresque", "Mosaïque", "Sculpture sur marbre", "Vitrail"), 2, "Art", Difficulty.EXPERT, explanation = "La sculpture sur marbre est réputée pour sa lenteur d'exécution en raison de la dureté du matériau et de la précision nécessaire pour éviter les éclats."),
        Question(50925, "Quel est le matériau le plus utilisé en sculpture?", listOf("Bronze", "Marbre", "Pierre", "Bois"), 1, "Art", Difficulty.HARD, explanation = "Le marbre est privilégié en sculpture depuis l'Antiquité pour sa dureté, sa texture fine et sa capacité à être poli, permettant des détails précis et une luminosité naturelle.")
    )

    private fun litterature(): List<Question> = listOf(
        // ===== LITTÉRATURE (75 questions) =====
        Question(51000, "Quel est l'auteur de 'Don Quichotte'?", listOf("Lope de Vega", "Miguel de Cervantes", "Calderón de la Barca", "García Lorca"), 1, "Littérature", Difficulty.EASY, explanation = "Miguel de Cervantes a publié la première partie de Don Quichotte en 1605, une œuvre majeure de la littérature espagnole et mondiale."),
        Question(51001, "Quel est l'auteur de 'Les Misérables'?", listOf("Alexandre Dumas", "Victor Hugo", "Émile Zola", "Gustave Flaubert"), 1, "Littérature", Difficulty.EASY, explanation = "Victor Hugo a publié Les Misérables en 1862. Ce roman majeur du XIXe siècle dépeint la société française de l'époque à travers des personnages comme Jean Valjean."),
        Question(51002, "Quel est l'auteur de 'Jane Eyre'?", listOf("George Eliot", "Charlotte Brontë", "Emily Dickinson", "Jane Austen"), 1, "Littérature", Difficulty.EASY, explanation = "Charlotte Brontë a publié 'Jane Eyre' en 1847 sous le pseudonyme Currer Bell, un roman majeur de la littérature victorienne."),
        Question(51003, "Quel est l'auteur de 'Les Hauts de Hurlevent'?", listOf("George Eliot", "Charlotte Brontë", "Emily Brontë", "Jane Austen"), 2, "Littérature", Difficulty.EASY, explanation = "Emily Brontë a publié ce roman en 1847 sous le pseudonyme masculin Ellis Bell, car les femmes autrices étaient peu acceptées à l'époque."),
        Question(51004, "Quel est l'auteur de 'Fierté et Préjugés'?", listOf("George Eliot", "Charlotte Brontë", "Emily Dickinson", "Jane Austen"), 3, "Littérature", Difficulty.EASY, explanation = "Jane Austen a publié \"Fierté et Préjugés\" en 1813, un roman majeur de la littérature anglaise qui critique la société et les mariages arrangés de son époque."),
        Question(51005, "Quel est l'auteur de 'Orgueill et Préjugés'?", listOf("George Eliot", "Charlotte Brontë", "Emily Dickinson", "Jane Austen"), 3, "Littérature", Difficulty.EASY, explanation = "Jane Austen a publié Orgueil et Préjugés en 1813, roman devenu un classique de la littérature anglaise pour sa critique sociale et son humour."),
        Question(51006, "Quel est l'auteur de 'Le Comte de Monte-Cristo'?", listOf("Alexandre Dumas", "Victor Hugo", "Émile Zola", "Gustave Flaubert"), 0, "Littérature", Difficulty.EASY, explanation = "Alexandre Dumas a publié ce roman d'aventures en feuilleton entre 1844 et 1846, s'inspirant d'un fait divers réel impliquant un cordonnier injustement emprisonné."),
        Question(51007, "Quel est l'auteur de 'Moby Dick'?", listOf("Nathaniel Hawthorne", "Herman Melville", "Mark Twain", "Harriet Beecher Stowe"), 1, "Littérature", Difficulty.EASY, explanation = "Herman Melville a publié Moby Dick en 1851, roman inspiré de ses expériences de marin et de l'histoire vraie du baleinier Essex."),
        Question(51008, "Quel est l'auteur de 'Cent ans de Solitude'?", listOf("Jorge Luis Borges", "Gabriel García Márquez", "Pablo Neruda", "Julio Cortázar"), 1, "Littérature", Difficulty.MEDIUM, explanation = "Gabriel García Márquez a écrit ce roman emblématique du réalisme magique, publié en 1967, qui lui a valu le prix Nobel de littérature en 1982."),
        Question(51009, "Quel est l'auteur de 'Crime et Châtiment'?", listOf("Dostoïevski", "Tolstoï", "Tourguéniev", "Pouchkine"), 0, "Littérature", Difficulty.EASY, explanation = "Fiodor Dostoïevski a publié ce roman majeur en 1866, explorant la psychologie d’un meurtrier et les thèmes de la culpabilité et de la rédemption."),
        Question(51010, "Quel est l'auteur de 'La Nuit de la Rue du Parc'?", listOf("Charles Baudelaire", "Victor Hugo", "Arthur Rimbaud", "Stéphane Mallarmé"), 2, "Littérature", Difficulty.HARD, explanation = "Arthur Rimbaud a écrit ce poème en 1870, à l'âge de 16 ans, dans le recueil \"Poésies\". Il y décrit une scène nocturne parisienne avec une ironie mordante."),
        Question(51011, "Quel est l'auteur de 'Madame Bovary'?", listOf("Honoré de Balzac", "Gustave Flaubert", "Émile Zola", "Stendhal"), 1, "Littérature", Difficulty.EASY, explanation = "Gustave Flaubert a publié Madame Bovary en 1857, un roman réaliste qui a marqué la littérature française par sa description minutieuse de la vie provinciale et de l'insatisfaction conjugale."),
        Question(51012, "Quel est l'auteur de 'Le Père Goriot'?", listOf("Honoré de Balzac", "Gustave Flaubert", "Émile Zola", "Stendhal"), 0, "Littérature", Difficulty.MEDIUM, explanation = "Honoré de Balzac a écrit Le Père Goriot en 1835, roman majeur de La Comédie humaine qui explore les thèmes de l'ambition et de la paternité dans le Paris du XIXe siècle."),
        Question(51013, "Quel est l'auteur de 'Le Rouge et le Noir'?", listOf("Honoré de Balzac", "Gustave Flaubert", "Stendhal", "Alexandre Dumas"), 2, "Littérature", Difficulty.MEDIUM, explanation = "Stendhal, de son vrai nom Henri Beyle, a publié ce roman en 1830, considéré comme un chef-d'œuvre du réalisme français."),
